import { AppState } from "../types";

const DB_NAME = "Prod360DB";
const STORE_NAME = "appState";
const DB_VERSION = 1;

export const dbService = {
  open(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(DB_NAME, DB_VERSION);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(STORE_NAME)) {
          db.createObjectStore(STORE_NAME);
        }
      };

      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  },

  async save(state: AppState): Promise<void> {
    const db = await this.open();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, "readwrite");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.put(state, "current_state");

      request.onsuccess = () => resolve();
      request.onerror = () => reject(request.error);
    });
  },

  async load(): Promise<AppState | null> {
    const db = await this.open();
    return new Promise((resolve, reject) => {
      const transaction = db.transaction(STORE_NAME, "readonly");
      const store = transaction.objectStore(STORE_NAME);
      const request = store.get("current_state");

      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error);
    });
  },

  async clear(): Promise<void> {
    const db = await this.open();
    const transaction = db.transaction(STORE_NAME, "readwrite");
    transaction.objectStore(STORE_NAME).clear();
  }
};

import React, { useState, useEffect } from 'react';
import { Person, Task, AppState, ServiceCategory, UserRole } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import PeopleManager from './components/PeopleManager';
import DailyLog from './components/DailyLog';
import ServiceManager from './components/ServiceManager';
import Login from './components/Login';
import { DEFAULT_CATEGORIES } from './constants';
import { dbService } from './services/db';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'people' | 'logs' | 'services'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  const [state, setState] = useState<AppState>({ 
    people: [], 
    tasks: [], 
    serviceCategories: DEFAULT_CATEGORIES,
    userRole: 'master' 
  });

  // Load state from IndexedDB on startup
  useEffect(() => {
    async function initDB() {
      try {
        const savedState = await dbService.load();
        if (savedState) {
          setState(savedState);
        }
      } catch (error) {
        console.error("Erro ao carregar banco de dados:", error);
      } finally {
        setTimeout(() => setIsLoading(false), 800); // Small delay for smooth splash screen
      }
    }
    initDB();
  }, []);

  // Save state to IndexedDB whenever it changes
  useEffect(() => {
    if (!isLoading) {
      dbService.save(state).catch(err => console.error("Erro ao salvar no DB:", err));
    }
  }, [state, isLoading]);

  const handleLogin = (role: UserRole) => {
    setState(prev => ({ ...prev, userRole: role }));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab('dashboard');
  };

  const setUserRole = (role: UserRole) => {
    setState(prev => ({ ...prev, userRole: role }));
    if (role === 'basic' && (activeTab === 'people' || activeTab === 'services')) {
      setActiveTab('dashboard');
    }
  };

  const addPerson = (person: Person) => {
    if (state.userRole !== 'master') return;
    setState(prev => ({ ...prev, people: [...prev.people, person] }));
  };

  const removePerson = (id: string) => {
    if (state.userRole !== 'master') return;
    setState(prev => ({
      ...prev,
      people: prev.people.filter(p => p.id !== id),
      tasks: prev.tasks.filter(t => t.personId !== id)
    }));
  };

  const addTask = (task: Task) => {
    setState(prev => ({ ...prev, tasks: [...prev.tasks, task] }));
  };

  const editTask = (updatedTask: Task) => {
    setState(prev => ({
      ...prev,
      tasks: prev.tasks.map(t => t.id === updatedTask.id ? updatedTask : t)
    }));
  };

  const removeTask = (id: string) => {
    if (state.userRole !== 'master') return;
    setState(prev => ({
      ...prev,
      tasks: prev.tasks.filter(t => t.id !== id)
    }));
  };

  const addServiceCategory = (cat: ServiceCategory) => {
    if (state.userRole !== 'master') return;
    setState(prev => ({ ...prev, serviceCategories: [...prev.serviceCategories, cat] }));
  };

  const removeServiceCategory = (id: string) => {
    if (state.userRole !== 'master') return;
    setState(prev => ({
      ...prev,
      serviceCategories: prev.serviceCategories.filter(c => c.id !== id),
      tasks: prev.tasks.filter(t => t.serviceCategoryId !== id)
    }));
  };

  const handleImportData = (importedState: AppState) => {
    setState(importedState);
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center">
        <div className="relative">
          <div className="w-20 h-20 border-4 border-blue-100 border-t-blue-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
             <svg className="w-8 h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
          </div>
        </div>
        <p className="mt-6 font-bold text-slate-400 uppercase tracking-widest text-xs animate-pulse">Conectando ao banco de dados...</p>
      </div>
    );
  }

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        userRole={state.userRole}
        onRoleChange={setUserRole}
        onLogout={handleLogout}
      />

      <main className="flex-1 p-6 md:p-10 overflow-auto">
        <header className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <h1 className="text-3xl font-bold text-slate-800">
              {activeTab === 'dashboard' && 'Visão Geral'}
              {activeTab === 'people' && 'Gerenciar Equipe'}
              {activeTab === 'logs' && 'Registro Diário'}
              {activeTab === 'services' && 'Tipos de Serviço'}
            </h1>
            <p className="text-slate-500 mt-2 font-medium">
              {activeTab === 'dashboard' && 'Monitore a produtividade e o desempenho da equipe.'}
              {activeTab === 'people' && 'Adicione ou remova membros da sua equipe.'}
              {activeTab === 'logs' && 'Visualize e gerencie os serviços realizados diariamente.'}
              {activeTab === 'services' && 'Personalize as categorias e gerencie a base de dados.'}
            </p>
          </div>

          <div className="flex items-center gap-3">
             <div className={`px-4 py-2 rounded-2xl text-[10px] font-bold uppercase tracking-widest shadow-sm ${
              state.userRole === 'master' ? 'bg-indigo-600 text-white' : 'bg-emerald-600 text-white'
            }`}>
              {state.userRole === 'master' ? 'Acesso Master' : 'Acesso Básico'}
            </div>
            <button 
              onClick={handleLogout}
              className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
              title="Sair do sistema"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
            </button>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <Dashboard state={state} />
        )}

        {activeTab === 'people' && state.userRole === 'master' && (
          <PeopleManager people={state.people} onAdd={addPerson} onRemove={removePerson} />
        )}

        {activeTab === 'logs' && (
          <DailyLog 
            tasks={state.tasks} 
            people={state.people} 
            categories={state.serviceCategories}
            onAddTask={addTask} 
            onEditTask={editTask}
            onRemoveTask={removeTask}
            userRole={state.userRole}
          />
        )}

        {activeTab === 'services' && state.userRole === 'master' && (
          <ServiceManager 
            categories={state.serviceCategories} 
            onAdd={addServiceCategory} 
            onRemove={removeServiceCategory} 
            state={state}
            onImport={handleImportData}
          />
        )}

        {(activeTab === 'people' || activeTab === 'services') && state.userRole === 'basic' && (
          <div className="bg-white p-12 rounded-3xl shadow-sm border border-slate-200 text-center">
            <div className="bg-slate-50 w-24 h-24 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-300">
              <svg className="w-12 h-12" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" /></svg>
            </div>
            <h2 className="text-2xl font-bold text-slate-800 mb-2">Acesso Restrito</h2>
            <p className="text-slate-500 max-w-sm mx-auto">Você está utilizando um perfil operacional (Básico) e não possui permissões para configurações de equipe ou serviços.</p>
            <button 
              onClick={() => setActiveTab('dashboard')}
              className="mt-8 bg-slate-900 text-white px-8 py-3 rounded-2xl font-bold hover:bg-black transition-all shadow-xl shadow-slate-200"
            >
              Retornar ao Painel
            </button>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { ServiceCategory, AppState } from '../types';
import { Icons, PRESET_COLORS } from '../constants';

interface ServiceManagerProps {
  categories: ServiceCategory[];
  onAdd: (category: ServiceCategory) => void;
  onRemove: (id: string) => void;
  state: AppState;
  onImport: (state: AppState) => void;
}

const ServiceManager: React.FC<ServiceManagerProps> = ({ categories, onAdd, onRemove, state, onImport }) => {
  const [name, setName] = useState('');
  const [selectedColor, setSelectedColor] = useState(PRESET_COLORS[0]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    onAdd({
      id: Math.random().toString(36).substr(2, 9),
      name: name.trim(),
      color: selectedColor
    });
    setName('');
  };

  const exportBackup = () => {
    const dataStr = JSON.stringify(state, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);

    const exportFileDefaultName = `prod360_backup_${new Date().toISOString().split('T')[0]}.json`;

    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const json = JSON.parse(event.target?.result as string);
        if (json.people && json.tasks && json.serviceCategories) {
          if (confirm("Isso irá substituir todos os dados atuais. Deseja continuar?")) {
            onImport(json);
            alert("Dados importados com sucesso!");
          }
        } else {
          alert("Arquivo inválido. Certifique-se de que é um backup do Prod360.");
        }
      } catch (err) {
        alert("Erro ao processar o arquivo.");
      }
    };
    reader.readAsText(file);
    e.target.value = ''; // Reset input
  };

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
        <div className="md:col-span-1 space-y-8">
          {/* Form Card */}
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
            <h3 className="text-lg font-bold text-slate-800 mb-6">Novo Tipo de Serviço</h3>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Nome do Serviço</label>
                <input
                  type="text"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Ex: Consultoria Externa"
                  className="w-full px-4 py-2 rounded-xl border border-slate-200 focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                  required
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-2">Cor de Identificação</label>
                <div className="flex flex-wrap gap-2">
                  {PRESET_COLORS.map(color => (
                    <button
                      key={color}
                      type="button"
                      onClick={() => setSelectedColor(color)}
                      className={`w-8 h-8 rounded-full border-2 transition-all ${selectedColor === color ? 'border-slate-900 scale-110' : 'border-transparent'}`}
                      style={{ backgroundColor: color }}
                    />
                  ))}
                </div>
              </div>
              <button
                type="submit"
                className="w-full bg-slate-800 text-white py-3 rounded-xl font-bold hover:bg-slate-900 transition-colors shadow-lg flex items-center justify-center gap-2"
              >
                <Icons.Plus />
                Salvar Serviço
              </button>
            </form>
          </div>

          {/* Database Card */}
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
            <div className="flex items-center gap-3 mb-6">
              <div className="p-2 bg-slate-100 rounded-lg text-slate-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 7v10c0 2.21 3.582 4 8 4s8-1.79 8-4V7M4 7c0 2.21 3.582 4 8 4s8-1.79 8-4M4 7c0-2.21 3.582-4 8-4s8 1.79 8 4m0 5c0 2.21-3.582 4-8 4s-8-1.79-8-4" /></svg>
              </div>
              <h3 className="text-lg font-bold text-slate-800">Banco de Dados</h3>
            </div>
            <p className="text-xs text-slate-500 mb-6 font-medium leading-relaxed">
              O sistema utiliza um banco de dados local (IndexedDB) que persiste automaticamente. 
              Para segurança, você pode exportar um backup físico.
            </p>
            <div className="space-y-3">
              <button
                onClick={exportBackup}
                className="w-full flex items-center justify-center gap-2 py-3 px-4 bg-blue-50 text-blue-700 rounded-xl font-bold text-sm hover:bg-blue-100 transition-colors"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
                Backup dos Dados (JSON)
              </button>
              <button
                onClick={handleImportClick}
                className="w-full flex items-center justify-center gap-2 py-3 px-4 bg-white border border-slate-200 text-slate-600 rounded-xl font-bold text-sm hover:bg-slate-50 transition-colors"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                Restaurar Backup
              </button>
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleFileChange} 
                className="hidden" 
                accept=".json"
              />
            </div>
          </div>
        </div>

        <div className="md:col-span-2">
          <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
            <div className="p-6 border-b border-slate-100 flex justify-between items-center">
              <h3 className="text-lg font-bold text-slate-800">Serviços Habilitados</h3>
              <span className="bg-slate-100 text-slate-600 px-3 py-1 rounded-full text-xs font-bold">
                {categories.length} Tipos
              </span>
            </div>

            <div className="divide-y divide-slate-100">
              {categories.length === 0 ? (
                <div className="p-10 text-center text-slate-400">
                  <p>Nenhum tipo de serviço configurado.</p>
                </div>
              ) : (
                categories.map((cat) => (
                  <div key={cat.id} className="p-4 flex items-center justify-between hover:bg-slate-50 transition-colors">
                    <div className="flex items-center gap-4">
                      <div className="w-4 h-4 rounded-full shadow-sm" style={{ backgroundColor: cat.color }}></div>
                      <span className="font-semibold text-slate-800">{cat.name}</span>
                    </div>
                    <button
                      onClick={() => onRemove(cat.id)}
                      className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                      title="Excluir tipo de serviço"
                    >
                      <Icons.Trash />
                    </button>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ServiceManager;

import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  doc, 
  onSnapshot, 
  setDoc, 
  getDoc 
} from "firebase/firestore";
import { AppState } from "../types";

// NOTA: Em um ambiente de produção, estas chaves viriam de variáveis de ambiente.
// Para este projeto, o Firebase será inicializado com uma config padrão.
// Você deve substituir pelos dados do seu projeto no Console do Firebase (firebase.google.com)
const firebaseConfig = {
  apiKey: "AIzaSyAs-DEMO-ONLY-KEY",
  authDomain: "prod360-demo.firebaseapp.com",
  projectId: "prod360-demo", // Substitua pelo seu Project ID do Firebase
  storageBucket: "prod360-demo.appspot.com",
  messagingSenderId: "123456789",
  appId: "1:123456789:web:abcdef"
};

const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

export const cloudDb = {
  /**
   * Escuta alterações em tempo real para um grupo específico
   */
  listenToGroup(groupId: string, callback: (state: AppState) => void) {
    const docRef = doc(db, "groups", groupId);
    return onSnapshot(docRef, (docSnap) => {
      if (docSnap.exists()) {
        callback(docSnap.data() as AppState);
      }
    });
  },

  /**
   * Salva o estado atual na nuvem
   */
  async syncState(groupId: string, state: AppState) {
    const docRef = doc(db, "groups", groupId);
    try {
      await setDoc(docRef, state, { merge: true });
    } catch (error) {
      console.error("Erro ao sincronizar com nuvem:", error);
    }
  },

  /**
   * Tenta carregar um estado inicial
   */
  async fetchState(groupId: string): Promise<AppState | null> {
    const docRef = doc(db, "groups", groupId);
    const docSnap = await getDoc(docRef);
    return docSnap.exists() ? (docSnap.data() as AppState) : null;
  }
};

import React, { useState, useEffect } from 'react';
import { Person, Task, AppState, ServiceCategory, UserRole } from './types';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import PeopleManager from './components/PeopleManager';
import DailyLog from './components/DailyLog';
import ServiceManager from './components/ServiceManager';
import Login from './components/Login';
import { DEFAULT_CATEGORIES } from './constants';
import { dbService } from './services/db';
import { cloudDb } from './services/cloudDb';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dashboard' | 'people' | 'logs' | 'services'>('dashboard');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [syncCode, setSyncCode] = useState<string>(localStorage.getItem('prod360_sync_code') || '');
  const [isCloudEnabled, setIsCloudEnabled] = useState(!!localStorage.getItem('prod360_sync_code'));

  const [state, setState] = useState<AppState>({ 
    people: [], 
    tasks: [], 
    serviceCategories: DEFAULT_CATEGORIES,
    userRole: 'master' 
  });

  // 1. Carregamento Inicial (Local ou Nuvem)
  useEffect(() => {
    async function init() {
      try {
        if (isCloudEnabled && syncCode) {
          // Se nuvem estiver ativa, o onSnapshot cuidará do estado (definido abaixo)
          const cloudState = await cloudDb.fetchState(syncCode);
          if (cloudState) setState(cloudState);
        } else {
          const savedState = await dbService.load();
          if (savedState) setState(savedState);
        }
      } catch (error) {
        console.error("Erro no carregamento inicial:", error);
      } finally {
        setTimeout(() => setIsLoading(false), 800);
      }
    }
    init();
  }, [isCloudEnabled]); // Recarrega se alternar modo nuvem

  // 2. Escuta em Tempo Real (Firebase)
  useEffect(() => {
    let unsubscribe: (() => void) | undefined;

    if (isCloudEnabled && syncCode) {
      unsubscribe = cloudDb.listenToGroup(syncCode, (newState) => {
        // Só atualiza se for diferente para evitar loops infinitos
        setState(newState);
      });
    }

    return () => {
      if (unsubscribe) unsubscribe();
    };
  }, [isCloudEnabled, syncCode]);

  // 3. Persistência de Saída (Salvar alterações)
  const persistState = async (newState: AppState) => {
    setState(newState);
    if (isCloudEnabled && syncCode) {
      await cloudDb.syncState(syncCode, newState);
    } else {
      await dbService.save(newState);
    }
  };

  const handleLogin = (role: UserRole) => {
    setState(prev => ({ ...prev, userRole: role }));
    setIsLoggedIn(true);
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setActiveTab('dashboard');
  };

  const setUserRole = (role: UserRole) => {
    persistState({ ...state, userRole: role });
    if (role === 'basic' && (activeTab === 'people' || activeTab === 'services')) {
      setActiveTab('dashboard');
    }
  };

  const toggleCloud = (code: string) => {
    if (code) {
      setSyncCode(code);
      setIsCloudEnabled(true);
      localStorage.setItem('prod360_sync_code', code);
    } else {
      setSyncCode('');
      setIsCloudEnabled(false);
      localStorage.removeItem('prod360_sync_code');
    }
  };

  // Funções de manipulação de dados atualizadas para persistir
  const addPerson = (person: Person) => {
    if (state.userRole !== 'master') return;
    persistState({ ...state, people: [...state.people, person] });
  };

  const removePerson = (id: string) => {
    if (state.userRole !== 'master') return;
    persistState({
      ...state,
      people: state.people.filter(p => p.id !== id),
      tasks: state.tasks.filter(t => t.personId !== id)
    });
  };

  const addTask = (task: Task) => {
    persistState({ ...state, tasks: [...state.tasks, task] });
  };

  const editTask = (updatedTask: Task) => {
    persistState({
      ...state,
      tasks: state.tasks.map(t => t.id === updatedTask.id ? updatedTask : t)
    });
  };

  const removeTask = (id: string) => {
    if (state.userRole !== 'master') return;
    persistState({
      ...state,
      tasks: state.tasks.filter(t => t.id !== id)
    });
  };

  const addServiceCategory = (cat: ServiceCategory) => {
    if (state.userRole !== 'master') return;
    persistState({ ...state, serviceCategories: [...state.serviceCategories, cat] });
  };

  const removeServiceCategory = (id: string) => {
    if (state.userRole !== 'master') return;
    persistState({
      ...state,
      serviceCategories: state.serviceCategories.filter(c => c.id !== id),
      tasks: state.tasks.filter(t => t.serviceCategoryId !== id)
    });
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center">
        <div className="relative">
          <div className="w-20 h-20 border-4 border-blue-100 border-t-blue-600 rounded-full animate-spin"></div>
          <div className="absolute inset-0 flex items-center justify-center">
             <svg className="w-8 h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
          </div>
        </div>
        <p className="mt-6 font-bold text-slate-400 uppercase tracking-widest text-xs animate-pulse">Sincronizando dados...</p>
      </div>
    );
  }

  if (!isLoggedIn) {
    return <Login onLogin={handleLogin} />;
  }

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        userRole={state.userRole}
        onRoleChange={setUserRole}
        onLogout={handleLogout}
      />

      <main className="flex-1 p-6 md:p-10 overflow-auto">
        <header className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div>
            <div className="flex items-center gap-3 mb-1">
              <h1 className="text-3xl font-bold text-slate-800">
                {activeTab === 'dashboard' && 'Visão Geral'}
                {activeTab === 'people' && 'Gerenciar Equipe'}
                {activeTab === 'logs' && 'Registro Diário'}
                {activeTab === 'services' && 'Tipos de Serviço'}
              </h1>
              {isCloudEnabled ? (
                <div className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 text-emerald-600 rounded-full text-[10px] font-bold uppercase tracking-wider border border-emerald-100 animate-pulse-slow">
                  <div className="w-1.5 h-1.5 rounded-full bg-emerald-500"></div>
                  Nuvem Ativa: {syncCode}
                </div>
              ) : (
                <div className="flex items-center gap-1.5 px-3 py-1 bg-slate-100 text-slate-500 rounded-full text-[10px] font-bold uppercase tracking-wider border border-slate-200">
                  Modo Local
                </div>
              )}
            </div>
            <p className="text-slate-500 font-medium">
              {activeTab === 'dashboard' && 'Monitore a produtividade e o desempenho da equipe.'}
              {activeTab === 'people' && 'Adicione ou remova membros da sua equipe.'}
              {activeTab === 'logs' && 'Visualize e gerencie os serviços realizados diariamente.'}
              {activeTab === 'services' && 'Personalize as categorias e gerencie a base de dados.'}
            </p>
          </div>

          <div className="flex items-center gap-3">
             <div className={`px-4 py-2 rounded-2xl text-[10px] font-bold uppercase tracking-widest shadow-sm ${
              state.userRole === 'master' ? 'bg-indigo-600 text-white' : 'bg-emerald-600 text-white'
            }`}>
              {state.userRole === 'master' ? 'Acesso Master' : 'Acesso Básico'}
            </div>
          </div>
        </header>

        {/* Cloud Sync Config (Show only in Services for Master) */}
        {activeTab === 'services' && state.userRole === 'master' && (
          <div className="mb-8 bg-gradient-to-r from-blue-600 to-indigo-700 p-8 rounded-[32px] text-white shadow-xl shadow-blue-100">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
              <div className="max-w-md">
                <h2 className="text-xl font-bold mb-2 flex items-center gap-2">
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 15a4 4 0 004 4h9a5 5 0 10-.1-9.999 5.002 5.002 0 10-9.78 2.096A4.001 4.001 0 003 15z" /></svg>
                  Sincronização em Nuvem (Multi-usuário)
                </h2>
                <p className="text-blue-100 text-sm leading-relaxed">
                  Digite um código único para sua equipe. Todos que usarem o mesmo código verão os mesmos dados em tempo real.
