                />
                <button 
                  onClick={() => toggleCloud(syncCode)}
                  className={`px-8 py-3 rounded-2xl font-bold transition-all shadow-lg ${
                    isCloudEnabled ? 'bg-red-500 hover:bg-red-600 text-white' : 'bg-white text-blue-700 hover:bg-blue-50'
