import { AppState } from "../types";

// No Render, a API estará na mesma URL do frontend
const API_BASE = "/api";

export const cloudDb = {
  /**
   * No modelo sem Firebase (Websockets), simularemos o pooling ou 
   * apenas carregamento sob demanda para simplificar.
   */
  listenToGroup(groupId: string, callback: (state: AppState) => void) {
    // Simulando escuta em tempo real com polling a cada 10 segundos
    const interval = setInterval(async () => {
      const state = await this.fetchState(groupId);
      if (state) callback(state);
    }, 10000);

    return () => clearInterval(interval);
  },

  /**
   * Salva o estado atual no nosso servidor Node no Render
   */
  async syncState(groupId: string, state: AppState) {
    try {
      await fetch(`${API_BASE}/state/${groupId}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(state)
      });
    } catch (error) {
      console.error("Erro ao sincronizar com servidor Render:", error);
    }
  },

  /**
   * Carrega o estado do servidor
   */
  async fetchState(groupId: string): Promise<AppState | null> {
    try {
      const response = await fetch(`${API_BASE}/state/${groupId}`);
      if (response.ok) {
        return await response.json();
      }
      return null;
    } catch (error) {
      console.error("Erro ao carregar do servidor Render:", error);
      return null;
    }
  }
};

import express from 'express';
import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs/promises';
import cors from 'cors';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const app = express();
const PORT = process.env.PORT || 3000;
const DATA_PATH = path.join(__dirname, 'database.json');

app.use(cors());
app.use(express.json({ limit: '50mb' }));

// Garante que o arquivo de banco de dados exista
async function ensureDb() {
  try {
    await fs.access(DATA_PATH);
  } catch {
    await fs.writeFile(DATA_PATH, JSON.stringify({ groups: {} }));
  }
}

// API: Carregar estado
app.get('/api/state/:groupId', async (req, res) => {
  try {
    const { groupId } = req.params;
    const content = await fs.readFile(DATA_PATH, 'utf-8');
    const db = JSON.parse(content);
    const state = db.groups[groupId];

    if (state) {
      res.json(state);
    } else {
      res.status(404).json({ error: 'Grupo não encontrado' });
    }
  } catch (error) {
    res.status(500).json({ error: 'Erro ao ler banco de dados' });
  }
});

// API: Salvar estado
app.post('/api/state/:groupId', async (req, res) => {
  try {
    const { groupId } = req.params;
    const newState = req.body;

    const content = await fs.readFile(DATA_PATH, 'utf-8');
    const db = JSON.parse(content);

    db.groups[groupId] = newState;

    await fs.writeFile(DATA_PATH, JSON.stringify(db, null, 2));
    res.json({ success: true });
  } catch (error) {
    res.status(500).json({ error: 'Erro ao salvar banco de dados' });
  }
});

// Serve os arquivos estáticos do frontend (pasta dist após o build)
app.use(express.static(path.join(__dirname, 'dist')));

// Redireciona qualquer outra rota para o index.html (SPA)
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'dist', 'index.html'));
});

ensureDb().then(() => {
  app.listen(PORT, () => {
    console.log(`Servidor Prod360 rodando em: http://localhost:${PORT}`);
  });
});

