import { initializeApp } from "firebase/app";
import { 
  getFirestore, 
  doc, 
  onSnapshot, 
  setDoc, 
  getDoc 
} from "firebase/firestore";
import { AppState } from "../types";

/**
 * IMPORTANTE: Substitua os valores abaixo pelas configurações do seu projeto Firebase.
 * Você encontra isso no Console do Firebase > Configurações do Projeto.
 */
const firebaseConfig = {
  apiKey: "SUA_API_KEY_DO_FIREBASE",
  authDomain: "seu-projeto.firebaseapp.com",
  projectId: "seu-projeto",
  storageBucket: "seu-projeto.appspot.com",
  messagingSenderId: "seu-id",
  appId: "seu-app-id"
};

// Inicializa o Firebase (apenas se houver configuração válida)
const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

export const cloudDb = {
  /**
   * Escuta alterações em tempo real no documento do grupo
   */
  listenToGroup(groupId: string, callback: (state: AppState) => void) {
    if (!groupId) return () => {};

    const docRef = doc(db, "groups", groupId);

    // O onSnapshot do Firebase é o "pulo do gato" para tempo real
    return onSnapshot(docRef, (docSnap) => {
      if (docSnap.exists()) {
        callback(docSnap.data() as AppState);
      }
    });
  },

  /**
   * Sincroniza o estado local com o Firestore
   */
  async syncState(groupId: string, state: AppState) {
    if (!groupId) return;
    try {
      const docRef = doc(db, "groups", groupId);
      await setDoc(docRef, state, { merge: true });
    } catch (error) {
      console.error("Erro ao sincronizar com Firestore:", error);
    }
  },

  /**
   * Busca o estado inicial uma única vez
   */
  async fetchState(groupId: string): Promise<AppState | null> {
    if (!groupId) return null;
    try {
      const docRef = doc(db, "groups", groupId);
      const docSnap = await getDoc(docRef);
      if (docSnap.exists()) {
        return docSnap.data() as AppState;
      }
      return null;
    } catch (error) {
      console.error("Erro ao buscar do Firestore:", error);
      return null;
    }
  }
};

