import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  const today = new Date().toISOString().split('T')[0];
  const lastWeek = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  const [startDate, setStartDate] = useState<string>(lastWeek);
  const [endDate, setEndDate] = useState<string>(today);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Filtro centralizado por período de datas
  const filteredTasks = useMemo(() => {
    return state.tasks.filter(t => t.date >= startDate && t.date <= endDate);
  }, [state.tasks, startDate, endDate]);

  // Atalhos de período
  const setRangePreset = (days: number) => {
    const end = new Date().toISOString().split('T')[0];
    const start = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    setStartDate(start);
    setEndDate(end);
  };

  // Dados para o Gráfico de Evolução (Linha/Área)
  const evolutionData = useMemo(() => {
    const dates: Record<string, any> = {};

    // Criar slots para cada dia no intervalo selecionado para garantir que o gráfico não tenha buracos
    const start = new Date(startDate + 'T00:00:00');
    const end = new Date(endDate + 'T00:00:00');
    const diffTime = Math.abs(end.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    // Limitar a geração de pontos para evitar travamentos em intervalos gigantes
    const maxDays = diffDays > 365 ? 365 : diffDays;

    for (let i = 0; i <= maxDays; i++) {
      const d = new Date(start);
      d.setDate(d.getDate() + i);
      const dateStr = d.toISOString().split('T')[0];
      dates[dateStr] = { date: dateStr, total: 0 };
      state.serviceCategories.forEach(cat => {
        dates[dateStr][cat.name] = 0;
      });
    }

    filteredTasks.forEach(t => {
      if (dates[t.date]) {
        const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
        if (cat) {
          dates[t.date][cat.name] += t.quantity;
          dates[t.date].total += t.quantity;
        }
      }
    });

    return Object.values(dates).sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [filteredTasks, state.serviceCategories, startDate, endDate]);

  // Ranking da Equipe
  const teamData = useMemo(() => {
    const data = state.people.map(person => {
      const total = filteredTasks
        .filter(t => t.personId === person.id)
        .reduce((sum, t) => sum + t.quantity, 0);
      return {
        name: person.name,
        quantity: total
      };
    });
    return data.sort((a, b) => b.quantity - a.quantity);
  }, [filteredTasks, state.people]);

  // Distribuição por Categoria
  const categoryData = useMemo(() => {
    const counts: Record<string, number> = {};
    state.serviceCategories.forEach(cat => counts[cat.id] = 0);

    filteredTasks.forEach(t => {
      if (counts[t.serviceCategoryId] !== undefined) {
        counts[t.serviceCategoryId] += t.quantity;
      }
    });

    return state.serviceCategories.map(cat => ({
      name: cat.name,
      value: counts[cat.id],
      color: cat.color
    })).filter(item => item.value > 0);
  }, [filteredTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    setLoadingAi(true);
    const result = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
    setAiInsight(result || "Não foi possível gerar insights no momento.");
    setLoadingAi(false);
  };

  const totalQuantity = filteredTasks.reduce((acc, t) => acc + t.quantity, 0);

  return (
    <div className="space-y-8">
      {/* Seletor de Período Refatorado */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <div className="bg-blue-600 p-2.5 rounded-2xl text-white shadow-lg shadow-blue-100">
              <Icons.Calendar />
            </div>
            <div>
              <h3 className="font-bold text-slate-800 text-lg">Período de Análise</h3>
              <p className="text-xs text-slate-400 font-medium">Selecione o intervalo de datas para os gráficos</p>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-4">
            <div className="flex items-center gap-2 bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
              <div className="flex flex-col px-3">
                <label className="text-[10px] font-black uppercase text-slate-400">De</label>
                <input 
                  type="date" 
                  value={startDate} 
                  onChange={(e) => setStartDate(e.target.value)}
                  className="bg-transparent text-sm font-bold text-slate-700 outline-none"
                />
              </div>
              <div className="w-px h-8 bg-slate-200"></div>
              <div className="flex flex-col px-3">
                <label className="text-[10px] font-black uppercase text-slate-400">Até</label>
                <input 
                  type="date" 
                  value={endDate} 
                  onChange={(e) => setEndDate(e.target.value)}
                  className="bg-transparent text-sm font-bold text-slate-700 outline-none"
                />
              </div>
            </div>

            <div className="flex gap-2">
              <button onClick={() => setRangePreset(0)} className="px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold hover:bg-slate-50 transition-all">Hoje</button>
              <button onClick={() => setRangePreset(7)} className="px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold hover:bg-slate-50 transition-all">7d</button>
              <button onClick={() => setRangePreset(30)} className="px-3 py-2 bg-white border border-slate-200 rounded-xl text-xs font-bold hover:bg-slate-50 transition-all">30d</button>
            </div>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-bold uppercase tracking-wider">Total no Período</p>
          <div className="flex items-baseline gap-2 mt-2">
            <p className="text-5xl font-black text-slate-900">{totalQuantity}</p>
            <span className="text-slate-400 font-bold text-sm">itens</span>
          </div>
        </div>
        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-bold uppercase tracking-wider">Colaboradores</p>
          <div className="flex items-baseline gap-2 mt-2">
            <p className="text-5xl font-black text-slate-900">{state.people.length}</p>
            <span className="text-slate-400 font-bold text-sm">ativos</span>
          </div>
        </div>
        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
          <p className="text-slate-500 text-sm font-bold uppercase tracking-wider">Registros</p>
          <div className="flex items-baseline gap-2 mt-2">
            <p className="text-5xl font-black text-slate-900">{filteredTasks.length}</p>
            <span className="text-slate-400 font-bold text-sm">lançamentos</span>
          </div>
        </div>
      </div>

      {/* Gráfico Principal */}
      <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
        <h3 className="text-xl font-extrabold text-slate-800 mb-8">Evolução da Produtividade</h3>
        <div className="h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={evolutionData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis 
                dataKey="date" 
                tickFormatter={(val) => val.split('-').reverse().slice(0, 2).join('/')}
                stroke="#94a3b8"
                fontSize={11}
              />
              <YAxis stroke="#94a3b8" fontSize={11} />
              <Tooltip />
              <Legend />
              <Area type="monotone" dataKey="total" name="Total" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.1} strokeWidth={3} />
              {state.serviceCategories.map(cat => (
                <Area key={cat.id} type="monotone" dataKey={cat.name} stackId="1" stroke={cat.color} fill={cat.color} fillOpacity={0.2} />
              ))}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200 h-[450px]">
          <h3 className="text-xl font-extrabold text-slate-800 mb-8">Ranking da Equipe</h3>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={teamData} layout="vertical">
              <XAxis type="number" hide />
              <YAxis dataKey="name" type="category" width={100} fontSize={12} fontWeight={700} />
              <Tooltip />
              <Bar dataKey="quantity" fill="#3b82f6" radius={[0, 10, 10, 0]} barSize={20} />
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200 h-[450px]">
          <h3 className="text-xl font-extrabold text-slate-800 mb-8">Distribuição de Serviços</h3>
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie data={categoryData} cx="50%" cy="50%" innerRadius={70} outerRadius={100} paddingAngle={5} dataKey="value">
                {categoryData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* AI Insights Section */}
      <div className="bg-slate-900 rounded-[40px] p-10 text-white shadow-2xl relative overflow-hidden group">
        <div className="flex flex-col md:flex-row items-center justify-between gap-12 relative z-10">
          <div className="flex-1">
            <div className="flex items-center gap-4 mb-6">
              <div className="bg-blue-600 p-3 rounded-2xl">
                <Icons.Sparkles />
              </div>
              <h2 className="text-3xl font-black tracking-tight">Análise com IA</h2>
            </div>
            <p className="text-slate-400 text-lg mb-10 max-w-lg leading-relaxed">
              Clique para analisar a produção do período de <strong>{startDate.split('-').reverse().join('/')}</strong> até <strong>{endDate.split('-').reverse().join('/')}</strong>.
            </p>
            {!aiInsight && !loadingAi && (
              <button 
                onClick={handleGetInsights}
                className="bg-white text-slate-900 px-10 py-5 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-blue-50 transition-all shadow-2xl"
              >
                Gerar Insights do Período
              </button>
            )}
          </div>

          {loadingAi && <div className="animate-spin h-12 w-12 border-4 border-white/20 border-t-white rounded-full"></div>}

          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/5 backdrop-blur-3xl rounded-[32px] p-8 border border-white/10 max-h-[400px] overflow-y-auto custom-scrollbar">
              <div className="text-base leading-relaxed whitespace-pre-wrap font-medium text-slate-200">
                {aiInsight}
              </div>
              <button onClick={() => setAiInsight(null)} className="mt-6 text-xs font-bold text-slate-500 hover:text-white transition-all uppercase tracking-widest">Limpar Análise</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Person, Task, ServiceCategory, UserRole } from '../types';
import { Icons } from '../constants';

interface DailyLogProps {
  tasks: Task[];
  people: Person[];
  categories: ServiceCategory[];
  onAddTask: (task: Task) => void;
  onEditTask: (task: Task) => void;
  onRemoveTask: (id: string) => void;
  userRole: UserRole;
}

const DailyLog: React.FC<DailyLogProps> = ({ tasks, people, categories, onAddTask, onEditTask, onRemoveTask, userRole }) => {
  const [selectedPerson, setSelectedPerson] = useState('');
  const [selectedCategoryId, setSelectedCategoryId] = useState('');
  const [invoiceNumber, setInvoiceNumber] = useState(''); // Alterado de description
  const [quantity, setQuantity] = useState<number>(1);
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const [filterDate, setFilterDate] = useState(new Date().toISOString().split('T')[0]);
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);

  const filteredTasks = useMemo(() => {
    return tasks
      .filter(t => t.date === filterDate)
      .sort((a, b) => b.id.localeCompare(a.id));
  }, [tasks, filterDate]);

  const handleSaveTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPerson || !selectedCategoryId || !invoiceNumber.trim()) return;

    if (editingTaskId) {
      onEditTask({
        id: editingTaskId,
        personId: selectedPerson,
        serviceCategoryId: selectedCategoryId,
        invoiceNumber: invoiceNumber.trim(),
        date,
        quantity: quantity
      });
      setEditingTaskId(null);
    } else {
      onAddTask({
        id: Math.random().toString(36).substr(2, 9),
        personId: selectedPerson,
        serviceCategoryId: selectedCategoryId,
        invoiceNumber: invoiceNumber.trim(),
        date,
        quantity: quantity
      });
    }

    setInvoiceNumber('');
    setQuantity(1);
    setSelectedPerson('');
    setSelectedCategoryId('');
  };

  const startEdit = (task: Task) => {
    setEditingTaskId(task.id);
    setSelectedPerson(task.personId);
    setSelectedCategoryId(task.serviceCategoryId);
    setInvoiceNumber(task.invoiceNumber);
    setQuantity(task.quantity);
    setDate(task.date);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cancelEdit = () => {
    setEditingTaskId(null);
    setInvoiceNumber('');
    setQuantity(1);
    setSelectedPerson('');
    setSelectedCategoryId('');
  };

  return (
    <div className="space-y-8">
      <div className={`bg-white p-6 rounded-2xl shadow-sm border transition-all ${editingTaskId ? 'border-amber-400 ring-2 ring-amber-50' : 'border-slate-200'}`}>
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-lg font-bold text-slate-800">
            {editingTaskId ? 'Editar Registro' : 'Novo Registro de Produção'}
          </h3>
          {editingTaskId && (
            <button onClick={cancelEdit} className="text-xs font-bold text-amber-600 bg-amber-50 px-3 py-1.5 rounded-lg">Cancelar Edição</button>
          )}
        </div>

        <form onSubmit={handleSaveTask} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4 items-end">
          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 mb-1">Data</label>
            <input type="date" value={date} onChange={(e) => setDate(e.target.value)} className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none" />
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 mb-1">Colaborador</label>
            <select value={selectedPerson} onChange={(e) => setSelectedPerson(e.target.value)} className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none" required>
              <option value="">Selecione...</option>
              {people.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-[10px] font-black uppercase text-slate-400 mb-1">Serviço</label>
            <select value={selectedCategoryId} onChange={(e) => setSelectedCategoryId(e.target.value)} className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none" required>
              <option value="">Selecione...</option>
              {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
            </select>
          </div>
          <div className="lg:col-span-2">
            <label className="block text-[10px] font-black uppercase text-slate-400 mb-1">Notas Fiscais / Ref.</label>
            <input
              type="text"
              value={invoiceNumber}
              onChange={(e) => setInvoiceNumber(e.target.value)}
              placeholder="Ex: NF-1234, NF-5678..."
              className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none focus:ring-2 focus:ring-blue-500"
              required
            />
          </div>
          <div className="flex gap-2">
            <div className="flex-1">
              <label className="block text-[10px] font-black uppercase text-slate-400 mb-1">Qtd</label>
              <input type="number" min="1" value={quantity} onChange={(e) => setQuantity(parseFloat(e.target.value))} className="w-full px-4 py-2 rounded-xl border border-slate-200 outline-none" />
            </div>
            <button type="submit" className={`${editingTaskId ? 'bg-amber-500' : 'bg-blue-600'} text-white p-2.5 rounded-xl mt-auto`}>
              {editingTaskId ? <Icons.Edit /> : <Icons.Plus />}
            </button>
          </div>
        </form>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center">
          <h3 className="text-lg font-bold text-slate-800">Registros do Dia</h3>
          <input type="date" value={filterDate} onChange={(e) => setFilterDate(e.target.value)} className="px-4 py-1.5 rounded-lg border border-slate-200 outline-none text-sm" />
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-slate-500 text-[10px] font-black uppercase tracking-widest">
              <tr>
                <th className="px-6 py-4">Colaborador</th>
                <th className="px-6 py-4">Serviço</th>
                <th className="px-6 py-4">Notas Fiscais</th>
                <th className="px-6 py-4 text-center">Qtd</th>
                <th className="px-6 py-4 text-right">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredTasks.length === 0 ? (
                <tr><td colSpan={5} className="px-6 py-12 text-center text-slate-400">Nenhum registro encontrado.</td></tr>
              ) : (
                filteredTasks.map((task) => {
                  const person = people.find(p => p.id === task.personId);
                  const category = categories.find(c => c.id === task.serviceCategoryId);
                  return (
                    <tr key={task.id} className="hover:bg-slate-50 transition-colors">
                      <td className="px-6 py-4">
                        <p className="font-bold text-slate-800 text-sm">{person?.name || '??'}</p>
                        <p className="text-[10px] text-slate-400 uppercase font-black">{person?.role}</p>
                      </td>
                      <td className="px-6 py-4">
                        <span className="px-2.5 py-1 rounded-full text-[10px] font-black text-white" style={{ backgroundColor: category?.color }}>
                          {category?.name}
                        </span>
                      </td>
                      <td className="px-6 py-4 text-sm font-medium text-slate-600">{task.invoiceNumber}</td>
                      <td className="px-6 py-4 text-center font-black text-slate-800">{task.quantity}</td>
                      <td className="px-6 py-4 text-right">
                        <div className="flex justify-end gap-1">
                          {userRole === 'master' && (
                            <>
                              <button onClick={() => startEdit(task)} className="p-2 text-slate-400 hover:text-blue-600"><Icons.Edit /></button>
                              <button onClick={() => onRemoveTask(task.id)} className="p-2 text-slate-400 hover:text-red-600"><Icons.Trash /></button>
                            </>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default DailyLog;

import { GoogleGenAI } from "@google/genai";
import { Task, Person, ServiceCategory } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getProductivityInsights(tasks: Task[], people: Person[], categories: ServiceCategory[]) {
  if (tasks.length === 0) return "Ainda não há dados suficientes para uma análise.";

  const prompt = `
    Analise os seguintes dados de produção quantitativa de uma equipe:

    Categorias de Serviço Monitoradas: ${categories.map(c => c.name).join(', ')}
    Equipe: ${people.map(p => p.name).join(', ')}

    Registros de Produção:
    ${tasks.map(t => {
      const p = people.find(person => person.id === t.personId);
      const c = categories.find(cat => cat.id === t.serviceCategoryId);
      return `- ${t.date}: ${p?.name} realizou ${c?.name} (Notas/Ref: ${t.invoiceNumber}) - Quantidade: ${t.quantity}.`;
    }).join('\n')}

    Por favor, forneça um resumo executivo focado nos volumes e na eficiência por categoria. Identifique gargalos e sugira melhorias estratégicas.
    Responda em Português do Brasil de forma profissional, direta e motivadora.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Erro ao obter insights da IA:", error);
    return "Desculpe, não foi possível gerar insights no momento.";
  }
}

export type UserRole = 'master' | 'basic';

export interface ServiceCategory {
  id: string;
  name: string;
  color: string;
}

export interface Person {
  id: string;
  name: string;
  role: string;
}

export interface Task {
  id: string;
  personId: string;
  serviceCategoryId: string; 
  invoiceQuantity: number; // Qtd de Notas Fiscais
  date: string; // ISO date string YYYY-MM-DD
  processQuantity: number; // Qtd de Processos (antigo quantity)
}

export interface AppState {
  people: Person[];
  tasks: Task[];
  serviceCategories: ServiceCategory[];
  userRole: UserRole;
}

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area
} from 'recharts';
import { AppState } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  const today = new Date().toISOString().split('T')[0];
  const lastMonth = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  const [startDate, setStartDate] = useState<string>(lastMonth);
  const [endDate, setEndDate] = useState<string>(today);
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Filtro por período
  const filteredTasks = useMemo(() => {
    return state.tasks.filter(t => t.date >= startDate && t.date <= endDate);
  }, [state.tasks, startDate, endDate]);

  // Evolução Diária (Volume total)
  const evolutionData = useMemo(() => {
    const dates: Record<string, any> = {};
    const start = new Date(startDate + 'T00:00:00');
    const end = new Date(endDate + 'T00:00:00');

    for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      const dateStr = d.toISOString().split('T')[0];
      dates[dateStr] = { date: dateStr, processos: 0, notas: 0 };
    }

    filteredTasks.forEach(t => {
      if (dates[t.date]) {
        dates[t.date].processos += t.processQuantity;
        dates[t.date].notas += (t.invoiceQuantity || 0);
      }
    });

    return Object.values(dates).sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [filteredTasks, startDate, endDate]);

  // Ranking com Duas Barras (Processos e Notas)
  const teamData = useMemo(() => {
    const data = state.people.map(person => {
      const pTasks = filteredTasks.filter(t => t.personId === person.id);
      const totalProcessos = pTasks.reduce((sum, t) => sum + t.processQuantity, 0);
      const totalNotas = pTasks.reduce((sum, t) => sum + (t.invoiceQuantity || 0), 0);
      return {
        name: person.name,
        processos: totalProcessos,
        notas: totalNotas
      };
    });
    return data.sort((a, b) => b.processos - a.processos);
  }, [filteredTasks, state.people]);

  // Distribuição por Categoria
  const categoryData = useMemo(() => {
    const counts: Record<string, number> = {};
    state.serviceCategories.forEach(cat => counts[cat.id] = 0);
    filteredTasks.forEach(t => {
      if (counts[t.serviceCategoryId] !== undefined) {
        counts[t.serviceCategoryId] += t.processQuantity;
      }
    });
    return state.serviceCategories.map(cat => ({
      name: cat.name,
      value: counts[cat.id],
      color: cat.color
    })).filter(item => item.value > 0);
  }, [filteredTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    setLoadingAi(true);
    const result = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
    setAiInsight(result || "Análise concluída.");
    setLoadingAi(false);
  };

  const totalProc = filteredTasks.reduce((acc, t) => acc + t.processQuantity, 0);
  const totalInv = filteredTasks.reduce((acc, t) => acc + (t.invoiceQuantity || 0), 0);

  return (
    <div className="space-y-8">
      {/* Seletor de Período (Intervalo de Datas) */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
        <div className="flex flex-col lg:flex-row items-center justify-between gap-6">
          <div className="flex items-center gap-4">
            <div className="bg-blue-600 p-3 rounded-2xl text-white">
              <Icons.Calendar />
            </div>
            <div>
              <h3 className="font-bold text-slate-800 text-lg leading-tight">Período de Análise</h3>
              <p className="text-xs text-slate-400 font-medium">Selecione o intervalo de datas</p>
            </div>
          </div>

          <div className="flex items-center gap-4 bg-slate-50 p-2 rounded-2xl border border-slate-100">
            <div className="flex flex-col px-3">
              <label className="text-[10px] font-black uppercase text-slate-400">De</label>
              <input 
                type="date" 
                value={startDate} 
                onChange={(e) => setStartDate(e.target.value)}
                className="bg-transparent text-sm font-bold text-slate-700 outline-none"
              />
            </div>
            <div className="w-px h-8 bg-slate-200"></div>
            <div className="flex flex-col px-3">
              <label className="text-[10px] font-black uppercase text-slate-400">Até</label>
              <input 
                type="date" 
                value={endDate} 
                onChange={(e) => setEndDate(e.target.value)}
                className="bg-transparent text-sm font-bold text-slate-700 outline-none"
              />
            </div>
          </div>
        </div>
      </div>

      {/* Cards de Métricas */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Total Processos</p>
          <p className="text-4xl font-black text-slate-900 mt-1">{totalProc}</p>
        </div>
        <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Total Notas Fiscais</p>
          <p className="text-4xl font-black text-emerald-600 mt-1">{totalInv}</p>
        </div>
        <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Equipe Ativa</p>
          <p className="text-4xl font-black text-slate-900 mt-1">{state.people.length}</p>
        </div>
        <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Média Notas/Proc.</p>
          <p className="text-4xl font-black text-blue-600 mt-1">{totalProc > 0 ? (totalInv / totalProc).toFixed(1) : 0}</p>
        </div>
      </div>

      {/* Gráfico Ranking de Equipe com Duas Barras */}
      <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
        <h3 className="text-xl font-extrabold text-slate-800 mb-8">Desempenho da Equipe: Processos vs Notas</h3>
        <div className="h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={teamData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={12} fontWeight={700} stroke="#64748b" />
              <YAxis axisLine={false} tickLine={false} fontSize={11} stroke="#94a3b8" />
              <Tooltip 
                cursor={{fill: '#f8fafc'}}
                contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }}
              />
              <Legend verticalAlign="top" align="right" wrapperStyle={{ paddingBottom: '20px' }} />
              <Bar dataKey="processos" name="Qtd. Processos" fill="#3b82f6" radius={[6, 6, 0, 0]} barSize={20} />
