              <AreaChart data={evolutionData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="date" 
                  tickFormatter={(val) => val.split('-').reverse().slice(0, 2).join('/')}
                  fontSize={10} stroke="#94a3b8" 
                />
                <YAxis fontSize={10} stroke="#94a3b8" />
