          <div className="space-y-8">
            <div>
              <div className="flex justify-between items-center mb-2">
                <span className="text-xs font-black text-slate-500 uppercase">Processos de Pagamento Comuns</span>
                <span className="text-sm font-black text-slate-800">{strategicAnalysis.commonsCount} unid.</span>
