                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Foco do Período</p>
                  <p className="text-sm font-bold text-slate-700">
                    {strategicAnalysis.specialsCount > strategicAnalysis.commonsCount 
                      ? "A equipe está focada em processos de Licitação e Diárias." 
                      : "A demanda predominante é de Pagamentos Comuns."}
                  </p>
                </div>
             </div>
          </div>
        </div>
      </div>

      {/* Gráfico Ranking Geral */}
      <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
        <h3 className="text-xl font-extrabold text-slate-800 mb-8">Ranking Geral de Equipe (Processos vs Notas)</h3>
        <div className="h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={teamData}>
