              <button onClick={handleGetInsights} className="bg-white text-slate-900 px-10 py-5 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-blue-50 transition-all shadow-2xl">Gerar Diagnóstico Estratégico</button>
