          {loadingAi && <div className="animate-spin h-12 w-12 border-4 border-white/20 border-t-white rounded-full"></div>}
          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/5 backdrop-blur-3xl rounded-[32px] p-8 border border-white/10 max-h-[400px] overflow-y-auto custom-scrollbar">
              <div className="text-base leading-relaxed whitespace-pre-wrap font-medium text-slate-200">{aiInsight}</div>
              <button onClick={() => setAiInsight(null)} className="mt-6 text-xs font-bold text-slate-500 hover:text-white uppercase tracking-widest">Limpar</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

type ProcessTypeFilter = 'all' | 'common' | 'special';

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  const today = new Date().toISOString().split('T')[0];
  const defaultStart = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  const [startDate, setStartDate] = useState<string>(defaultStart);
  const [endDate, setEndDate] = useState<string>(today);
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [processType, setProcessType] = useState<ProcessTypeFilter>('all');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Auxiliar para identificar tipos especiais
  const isSpecial = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    const name = cat?.name.toLowerCase() || "";
    return name.includes('licitação') || name.includes('diária') || name.includes('diaria');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  const selectAllPeople = () => setSelectedPeopleIds([]);

  // Filtro de tarefas robusto
  const filteredTasks = useMemo(() => {
    return state.tasks.filter(t => {
      const dateMatch = t.date >= startDate && t.date <= endDate;
      const personMatch = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);

      let typeMatch = true;
      if (processType === 'common') typeMatch = !isSpecial(t.serviceCategoryId);
      if (processType === 'special') typeMatch = isSpecial(t.serviceCategoryId);

      return dateMatch && personMatch && typeMatch;
    });
  }, [state.tasks, startDate, endDate, selectedPeopleIds, processType]);

  const setRangePreset = (days: number) => {
    const end = new Date().toISOString().split('T')[0];
    const start = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    setStartDate(start);
    setEndDate(end);
  };

  // --- LÓGICA DE AGRUPAMENTO ESTRATÉGICO (Cards e Pizza Específica) ---
  const strategicAnalysis = useMemo(() => {
    const specials = filteredTasks.filter(t => isSpecial(t.serviceCategoryId));
    const commons = filteredTasks.filter(t => !isSpecial(t.serviceCategoryId));

    const specialCategoriesMap: Record<string, number> = {};
    specials.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      if (cat) {
        specialCategoriesMap[cat.name] = (specialCategoriesMap[cat.name] || 0) + t.processQuantity;
      }
    });

    const specialPieData = Object.entries(specialCategoriesMap).map(([name, value]) => ({
      name,
      value,
      color: state.serviceCategories.find(c => c.name === name)?.color || '#3b82f6'
    }));

    return {
      specialsCount: specials.reduce((acc, t) => acc + t.processQuantity, 0),
      commonsCount: commons.reduce((acc, t) => acc + t.processQuantity, 0),
      specialPieData
    };
  }, [filteredTasks, state.serviceCategories]);

  // Ranking com Duas Barras
  const teamData = useMemo(() => {
    const peopleToAnalyze = selectedPeopleIds.length > 0 
      ? state.people.filter(p => selectedPeopleIds.includes(p.id))
      : state.people;

    const data = peopleToAnalyze.map(person => {
      const pTasks = filteredTasks.filter(t => t.personId === person.id);
      return {
        name: person.name,
        processos: pTasks.reduce((sum, t) => sum + t.processQuantity, 0),
        notas: pTasks.reduce((sum, t) => sum + (t.invoiceQuantity || 0), 0)
      };
    });
    return data.sort((a, b) => b.processos - a.processos);
  }, [filteredTasks, state.people, selectedPeopleIds]);

  // Gráfico de Evolução (Histórico)
  const evolutionData = useMemo(() => {
    const dates: Record<string, any> = {};
    const start = new Date(startDate + 'T00:00:00');
    const end = new Date(endDate + 'T00:00:00');

    for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      const dateStr = d.toISOString().split('T')[0];
      dates[dateStr] = { date: dateStr, processos: 0, notas: 0 };
    }

    filteredTasks.forEach(t => {
      if (dates[t.date]) {
        dates[t.date].processos += t.processQuantity;
        dates[t.date].notas += (t.invoiceQuantity || 0);
      }
    });

    return Object.values(dates).sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [filteredTasks, startDate, endDate]);

  // Distribuição Geral por Categoria
  const categoryData = useMemo(() => {
    const counts: Record<string, number> = {};
    state.serviceCategories.forEach(cat => counts[cat.id] = 0);
    filteredTasks.forEach(t => {
      if (counts[t.serviceCategoryId] !== undefined) {
        counts[t.serviceCategoryId] += t.processQuantity;
      }
    });
    return state.serviceCategories.map(cat => ({
      name: cat.name,
      value: counts[cat.id],
      color: cat.color
    })).filter(item => item.value > 0);
  }, [filteredTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
      setAiInsight(insight || "A IA não retornou insights válidos.");
    } catch (error) {
      console.error("Erro IA:", error);
      setAiInsight("Falha ao gerar insights da IA.");
    } finally {
      setLoadingAi(false);
    }
  };

  const totalProc = filteredTasks.reduce((acc, t) => acc + t.processQuantity, 0);
  const totalInv = filteredTasks.reduce((acc, t) => acc + (t.invoiceQuantity || 0), 0);
  const uniqueServicesCount = new Set(filteredTasks.map(t => t.serviceCategoryId)).size;

  return (
    <div className="space-y-8">
      {/* Bloco de Filtros Master */}
      <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200 space-y-8">
        {/* Seletor de Tipo de Processo (Novo) */}
        <div className="flex flex-col gap-4">
          <div className="flex items-center gap-4">
            <div className="bg-slate-800 p-3 rounded-2xl text-white">
              <Icons.Task />
            </div>
            <div>
              <h3 className="font-bold text-slate-800 text-lg leading-tight">Filtrar Carga por Tipo</h3>
              <p className="text-xs text-slate-400 font-medium">Selecione o grupo de processos para visualizar nos gráficos</p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2 p-1.5 bg-slate-50 rounded-2xl border border-slate-100 self-start">
            <button 
              onClick={() => setProcessType('all')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black tracking-widest transition-all ${processType === 'all' ? 'bg-white text-slate-900 shadow-sm border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}
            >
              TODOS
            </button>
            <button 
              onClick={() => setProcessType('common')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black tracking-widest transition-all ${processType === 'common' ? 'bg-white text-slate-700 shadow-sm border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}
            >
              PAGAMENTOS COMUNS
            </button>
            <button 
              onClick={() => setProcessType('special')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black tracking-widest transition-all ${processType === 'special' ? 'bg-amber-600 text-white shadow-lg shadow-amber-100' : 'text-slate-400 hover:text-slate-600'}`}
            >
              LICITAÇÃO / DIÁRIA
            </button>
          </div>
        </div>

        {/* Filtro de Período */}
        <div className="pt-6 border-t border-slate-100 flex flex-col gap-6">
          <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-4">
            <div className="flex items-center gap-4">
              <div className="bg-blue-600 p-3 rounded-2xl text-white">
                <Icons.Calendar />
              </div>
              <h3 className="font-bold text-slate-800 text-lg">Período de Análise</h3>
            </div>
            <div className="flex flex-wrap gap-2">
              {['HOJE', 'SEMANAL', 'QUINZENAL', 'MENSAL', 'TRIMESTRAL', 'ANUAL'].map((label, idx) => {
                const days = [0, 7, 15, 30, 90, 365][idx];
                return (
                  <button key={label} onClick={() => setRangePreset(days)} className="px-4 py-2 bg-slate-50 border border-slate-100 rounded-xl text-[10px] font-black tracking-widest text-slate-400 hover:bg-blue-600 hover:text-white transition-all">
                    {label}
                  </button>
                );
              })}
            </div>
          </div>
          <div className="flex items-center gap-4 bg-slate-50/50 p-3 rounded-2xl border border-slate-100 self-start">
            <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
            <div className="w-px h-6 bg-slate-200"></div>
            <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
          </div>
        </div>

        {/* Filtro de Equipe */}
        <div className="pt-6 border-t border-slate-100 flex flex-col gap-4">
          <div className="flex items-center gap-4">
            <div className="bg-indigo-100 p-3 rounded-2xl text-indigo-600">
              <Icons.People />
            </div>
            <h3 className="font-bold text-slate-800 text-lg leading-tight">Filtro de Equipe</h3>
          </div>
          <div className="flex flex-wrap gap-2">
            <button onClick={selectAllPeople} className={`px-5 py-2.5 rounded-2xl text-[11px] font-black border transition-all ${selectedPeopleIds.length === 0 ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-slate-400 border-slate-200'}`}>TODA A EQUIPE</button>
            {state.people.map(p => (
              <button key={p.id} onClick={() => togglePerson(p.id)} className={`px-5 py-2.5 rounded-2xl text-[11px] font-bold border flex items-center gap-2 transition-all ${selectedPeopleIds.includes(p.id) ? 'bg-indigo-50 text-indigo-700 border-indigo-200' : 'bg-white text-slate-500 border-slate-200'}`}>
                {p.name}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Cards de Métricas */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200 border-l-4 border-l-blue-500">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Processos ({processType === 'all' ? 'Total' : processType === 'common' ? 'Comuns' : 'Especiais'})</p>
          <p className="text-4xl font-black text-slate-900 mt-1">{totalProc}</p>
        </div>
        <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200 border-l-4 border-l-emerald-500">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Notas Fiscais</p>
          <p className="text-4xl font-black text-emerald-600 mt-1">{totalInv}</p>
        </div>
        <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200 border-l-4 border-l-amber-500">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Licitação / Diária</p>
          <p className="text-4xl font-black text-amber-600 mt-1">{strategicAnalysis.specialsCount}</p>
        </div>
        <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200 border-l-4 border-l-slate-400">
          <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Tipos de Serviços</p>
          <p className="text-4xl font-black text-slate-700 mt-1">{uniqueServicesCount}</p>
        </div>
      </div>

      {/* Seção Estratégica (Sempre visível para análise rápida) */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
          <h3 className="text-lg font-black text-slate-800 mb-2 uppercase tracking-tight">Carga Especial</h3>
          <p className="text-xs text-slate-400 font-bold mb-8">Somente Licitações e Diárias</p>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              {strategicAnalysis.specialPieData.length > 0 ? (
                <PieChart>
                  <Pie data={strategicAnalysis.specialPieData} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={8} dataKey="value">
                    {strategicAnalysis.specialPieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                  </Pie>
                  <Tooltip contentStyle={{ borderRadius: '12px', border: 'none' }} />
                  <Legend verticalAlign="bottom" />
                </PieChart>
              ) : (
                <div className="h-full flex items-center justify-center text-slate-300 text-[10px] font-black">SEM DADOS NESSE GRUPO</div>
              )}
            </ResponsiveContainer>
          </div>
        </div>

        <div className="lg:col-span-2 bg-white p-8 rounded-[32px] shadow-sm border border-slate-200 flex flex-col justify-center">
          <h3 className="text-lg font-black text-slate-800 mb-8 uppercase tracking-tight">Equilíbrio de Demanda</h3>
          <div className="space-y-6">
            <div>
              <div className="flex justify-between text-xs font-black text-slate-500 uppercase mb-2">
                <span>Processos Comuns</span>
                <span>{strategicAnalysis.commonsCount} unid.</span>
              </div>
              <div className="w-full bg-slate-100 h-4 rounded-full overflow-hidden">
                <div className="bg-slate-400 h-full transition-all duration-1000" style={{ width: `${(strategicAnalysis.commonsCount / (strategicAnalysis.commonsCount + strategicAnalysis.specialsCount || 1)) * 100}%` }}></div>
              </div>
            </div>
            <div>
              <div className="flex justify-between text-xs font-black text-amber-600 uppercase mb-2">
                <span>Licitação / Diária</span>
                <span>{strategicAnalysis.specialsCount} unid.</span>
              </div>
              <div className="w-full bg-amber-50 h-4 rounded-full overflow-hidden">
                <div className="bg-amber-500 h-full transition-all duration-1000" style={{ width: `${(strategicAnalysis.specialsCount / (strategicAnalysis.commonsCount + strategicAnalysis.specialsCount || 1)) * 100}%` }}></div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Gráficos Clássicos (Antigos) Restaurados */}
      <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
        <h3 className="text-xl font-extrabold text-slate-800 mb-8">Ranking Geral de Equipe</h3>
        <div className="h-96 w-full">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={teamData}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={12} fontWeight={700} stroke="#64748b" />
              <YAxis axisLine={false} tickLine={false} fontSize={11} stroke="#94a3b8" />
              <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '16px', border: 'none' }} />
              <Legend verticalAlign="top" align="right" />
              <Bar dataKey="processos" name="Processos" fill="#3b82f6" radius={[6, 6, 0, 0]} barSize={24} />
              <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[6, 6, 0, 0]} barSize={24} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
          <h3 className="text-xl font-extrabold text-slate-800 mb-8">Evolução do Trabalho</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={evolutionData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="date" tickFormatter={(v) => v.split('-').reverse().slice(0,2).join('/')} fontSize={10} stroke="#94a3b8" />
                <YAxis fontSize={10} stroke="#94a3b8" />
                <Tooltip />
                <Area type="monotone" dataKey="processos" name="Processos" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.1} strokeWidth={3} />
                <Area type="monotone" dataKey="notas" name="Notas" stroke="#10b981" fill="#10b981" fillOpacity={0.1} strokeWidth={3} />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
          <h3 className="text-xl font-extrabold text-slate-800 mb-8">Distribuição por Categoria</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={categoryData} cx="50%" cy="50%" innerRadius={60} outerRadius={90} paddingAngle={5} dataKey="value">
                  {categoryData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* IA Insights */}
      <div className="bg-slate-900 rounded-[40px] p-10 text-white shadow-2xl relative overflow-hidden group">
        <div className="flex flex-col md:flex-row items-center justify-between gap-12 relative z-10">
          <div className="flex-1">
            <div className="flex items-center gap-4 mb-6">
              <div className="bg-blue-600 p-3 rounded-2xl">
                <Icons.Sparkles />
              </div>
              <h2 className="text-3xl font-black tracking-tight">IA Diagnóstico</h2>
            </div>
            <p className="text-slate-400 text-lg mb-10 max-w-lg leading-relaxed font-medium">
              Análise profunda focada no filtro: <strong>{processType === 'all' ? 'Toda a carga' : processType === 'common' ? 'Pagamentos Comuns' : 'Especiais'}</strong>.
            </p>
            {!aiInsight && !loadingAi && (
              <button onClick={handleGetInsights} className="bg-white text-slate-900 px-10 py-5 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-blue-50 transition-all shadow-2xl">Gerar Análise IA</button>
            )}
          </div>
          {loadingAi && <div className="animate-spin h-12 w-12 border-4 border-white/20 border-t-white rounded-full"></div>}
          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/5 backdrop-blur-3xl rounded-[32px] p-8 border border-white/10 max-h-[400px] overflow-y-auto custom-scrollbar text-slate-200">
              <div className="text-base leading-relaxed whitespace-pre-wrap font-medium">{aiInsight}</div>
              <button onClick={() => setAiInsight(null)} className="mt-6 text-xs font-bold text-slate-500 hover:text-white uppercase tracking-widest">Limpar</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

type ProcessTypeFilter = 'all' | 'common' | 'special';

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  // Inicializa com os últimos 30 dias para garantir que dados recentes apareçam
  const today = new Date().toISOString().split('T')[0];
  const defaultStart = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  const [startDate, setStartDate] = useState<string>(defaultStart);
  const [endDate, setEndDate] = useState<string>(today);
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [processType, setProcessType] = useState<ProcessTypeFilter>('all');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Auxiliar para identificar tipos especiais (Licitação/Diária)
  const isSpecial = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase();
    // Normalização básica para evitar problemas com acentos
    const normalized = name.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return normalized.includes('licitacao') || normalized.includes('diaria') || normalized.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  const selectAllPeople = () => setSelectedPeopleIds([]);

  // Filtro de tarefas centralizado
  const filteredTasks = useMemo(() => {
    return state.tasks.filter(t => {
      // 1. Filtro de Data
      const dateMatch = t.date >= startDate && t.date <= endDate;
      // 2. Filtro de Equipe
      const personMatch = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
      // 3. Filtro de Tipo (Comum vs Especial)
      let typeMatch = true;
      if (processType === 'common') typeMatch = !isSpecial(t.serviceCategoryId);
      if (processType === 'special') typeMatch = isSpecial(t.serviceCategoryId);

      return dateMatch && personMatch && typeMatch;
    });
  }, [state.tasks, startDate, endDate, selectedPeopleIds, processType, state.serviceCategories]);

  const setRangePreset = (days: number) => {
    const end = new Date().toISOString().split('T')[0];
    const start = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    setStartDate(start);
    setEndDate(end);
  };

  // --- MÉTRICAS E GRÁFICOS ---
  const strategicAnalysis = useMemo(() => {
    const specials = filteredTasks.filter(t => isSpecial(t.serviceCategoryId));
    const commons = filteredTasks.filter(t => !isSpecial(t.serviceCategoryId));

    const specialCategoriesMap: Record<string, number> = {};
    specials.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      if (cat) {
        specialCategoriesMap[cat.name] = (specialCategoriesMap[cat.name] || 0) + t.processQuantity;
      }
    });

    const specialPieData = Object.entries(specialCategoriesMap).map(([name, value]) => ({
      name,
      value,
      color: state.serviceCategories.find(c => c.name === name)?.color || '#f59e0b'
    }));

    return {
      specialsCount: specials.reduce((acc, t) => acc + t.processQuantity, 0),
      commonsCount: commons.reduce((acc, t) => acc + t.processQuantity, 0),
      specialPieData
    };
  }, [filteredTasks, state.serviceCategories]);

  const teamData = useMemo(() => {
    const peopleToAnalyze = selectedPeopleIds.length > 0 
      ? state.people.filter(p => selectedPeopleIds.includes(p.id))
      : state.people;

    const data = peopleToAnalyze.map(person => {
      const pTasks = filteredTasks.filter(t => t.personId === person.id);
      return {
        name: person.name,
        processos: pTasks.reduce((sum, t) => sum + t.processQuantity, 0),
        notas: pTasks.reduce((sum, t) => sum + (t.invoiceQuantity || 0), 0)
      };
    });
    // Filtra pessoas sem produtividade no período para não sujar o gráfico
    return data.filter(d => d.processos > 0 || d.notas > 0).sort((a, b) => b.processos - a.processos);
  }, [filteredTasks, state.people, selectedPeopleIds]);

  const evolutionData = useMemo(() => {
    const dates: Record<string, any> = {};
    const start = new Date(startDate + 'T00:00:00');
    const end = new Date(endDate + 'T00:00:00');

    // Criar preenchimento de datas para evitar buracos no gráfico
    for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
      const dateStr = d.toISOString().split('T')[0];
      dates[dateStr] = { date: dateStr, processos: 0, notas: 0 };
    }

    filteredTasks.forEach(t => {
      if (dates[t.date]) {
        dates[t.date].processos += t.processQuantity;
        dates[t.date].notas += (t.invoiceQuantity || 0);
      }
    });

    return Object.values(dates).sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [filteredTasks, startDate, endDate]);

  const categoryData = useMemo(() => {
    const counts: Record<string, number> = {};
    state.serviceCategories.forEach(cat => counts[cat.id] = 0);
    filteredTasks.forEach(t => {
      if (counts[t.serviceCategoryId] !== undefined) {
        counts[t.serviceCategoryId] += t.processQuantity;
      }
    });
    return state.serviceCategories.map(cat => ({
      name: cat.name,
      value: counts[cat.id],
      color: cat.color
    })).filter(item => item.value > 0);
  }, [filteredTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (filteredTasks.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
      setAiInsight(insight || "A IA não retornou insights para os dados atuais.");
    } catch (error) {
      setAiInsight("Erro ao processar análise inteligente.");
    } finally {
      setLoadingAi(false);
    }
  };

  const totalProc = filteredTasks.reduce((acc, t) => acc + t.processQuantity, 0);
  const totalInv = filteredTasks.reduce((acc, t) => acc + (t.invoiceQuantity || 0), 0);
  const hasData = filteredTasks.length > 0;

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Bloco de Filtros Master */}
      <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200 space-y-8">
        {/* Seletor de Tipo de Processo */}
        <div className="flex flex-col gap-4">
          <div className="flex items-center gap-4">
            <div className="bg-slate-800 p-3 rounded-2xl text-white shadow-lg shadow-slate-100">
              <Icons.Task />
            </div>
            <div>
              <h3 className="font-bold text-slate-800 text-lg leading-tight">Tipo de Produtividade</h3>
              <p className="text-xs text-slate-400 font-medium">Filtre entre processos comuns ou licitações</p>
            </div>
          </div>
          <div className="flex flex-wrap gap-2 p-1.5 bg-slate-50 rounded-2xl border border-slate-100 self-start">
            <button 
              onClick={() => setProcessType('all')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black tracking-widest transition-all ${processType === 'all' ? 'bg-white text-blue-600 shadow-sm border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}
            >
              VISÃO TOTAL
            </button>
            <button 
              onClick={() => setProcessType('common')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black tracking-widest transition-all ${processType === 'common' ? 'bg-white text-slate-700 shadow-sm border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}
            >
              PAGAMENTOS COMUNS
            </button>
            <button 
              onClick={() => setProcessType('special')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black tracking-widest transition-all ${processType === 'special' ? 'bg-amber-600 text-white shadow-lg shadow-amber-100' : 'text-slate-400 hover:text-slate-600'}`}
            >
              LICITAÇÃO / DIÁRIA
            </button>
          </div>
        </div>

        {/* Filtro de Período */}
        <div className="pt-6 border-t border-slate-100 flex flex-col gap-6">
          <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-4">
            <div className="flex items-center gap-4 text-blue-600">
              <Icons.Calendar />
              <h3 className="font-bold text-slate-800 text-lg">Período Selecionado</h3>
            </div>
            <div className="flex flex-wrap gap-2">
              {['7D', '15D', '30D', '90D', '1A'].map((label, idx) => {
                const days = [7, 15, 30, 90, 365][idx];
                return (
                  <button key={label} onClick={() => setRangePreset(days)} className="px-4 py-2 bg-slate-50 border border-slate-100 rounded-xl text-[10px] font-black tracking-widest text-slate-400 hover:bg-blue-600 hover:text-white transition-all">
                    {label}
                  </button>
                );
              })}
            </div>
          </div>
          <div className="flex items-center gap-4 bg-slate-50/50 p-3 rounded-2xl border border-slate-100 self-start">
            <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
            <div className="w-px h-6 bg-slate-200"></div>
            <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
          </div>
        </div>

        {/* Filtro de Equipe */}
        <div className="pt-6 border-t border-slate-100 flex flex-col gap-4">
          <div className="flex items-center gap-4 text-indigo-600">
            <Icons.People />
            <h3 className="font-bold text-slate-800 text-lg">Equipe Analisada</h3>
          </div>
          <div className="flex flex-wrap gap-2">
            <button onClick={selectAllPeople} className={`px-5 py-2.5 rounded-2xl text-[11px] font-black border transition-all ${selectedPeopleIds.length === 0 ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-slate-400 border-slate-200 hover:border-indigo-300'}`}>TODA A EQUIPE</button>
            {state.people.map(p => (
              <button key={p.id} onClick={() => togglePerson(p.id)} className={`px-5 py-2.5 rounded-2xl text-[11px] font-bold border flex items-center gap-2 transition-all ${selectedPeopleIds.includes(p.id) ? 'bg-indigo-50 text-indigo-700 border-indigo-200 shadow-sm' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'}`}>
                <div className={`w-1.5 h-1.5 rounded-full ${selectedPeopleIds.includes(p.id) ? 'bg-indigo-600' : 'bg-slate-200'}`}></div>
                {p.name}
              </button>
            ))}
          </div>
        </div>
      </div>

      {!hasData ? (
        <div className="bg-white p-20 rounded-[40px] border border-dashed border-slate-300 flex flex-col items-center justify-center text-center">
          <div className="bg-slate-50 p-6 rounded-full text-slate-300 mb-6">
            <Icons.Calendar />
          </div>
          <h3 className="text-2xl font-bold text-slate-800 mb-2">Sem produtividade no período</h3>
          <p className="text-slate-500 max-w-sm">Não encontramos registros para os filtros selecionados. Tente expandir o período ou trocar o tipo de processo.</p>
        </div>
      ) : (
        <>
          {/* Cards de Métricas */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
            <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200 border-l-4 border-l-blue-500">
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Processos</p>
              <p className="text-4xl font-black text-slate-900 mt-1">{totalProc}</p>
            </div>
            <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200 border-l-4 border-l-emerald-500">
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Notas Fiscais</p>
              <p className="text-4xl font-black text-emerald-600 mt-1">{totalInv}</p>
            </div>
            <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200 border-l-4 border-l-amber-500">
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Licitação / Diária</p>
              <p className="text-4xl font-black text-amber-600 mt-1">{strategicAnalysis.specialsCount}</p>
            </div>
            <div className="bg-white p-6 rounded-[24px] shadow-sm border border-slate-200 border-l-4 border-l-indigo-500">
              <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">Analistas Ativos</p>
              <p className="text-4xl font-black text-indigo-600 mt-1">{teamData.length}</p>
            </div>
          </div>

          {/* Divisão Estratégica */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-1 bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
              <h3 className="text-lg font-black text-slate-800 mb-2 uppercase tracking-tight text-amber-600">Carga Especial</h3>
              <p className="text-xs text-slate-400 font-bold mb-8 italic">Licitação e Diárias detalhadas</p>
              <div className="h-64 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  {strategicAnalysis.specialPieData.length > 0 ? (
                    <PieChart>
                      <Pie data={strategicAnalysis.specialPieData} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={8} dataKey="value">
                        {strategicAnalysis.specialPieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                      </Pie>
                      <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', fontWeight: 'bold' }} />
                      <Legend verticalAlign="bottom" />
                    </PieChart>
                  ) : (
                    <div className="h-full flex items-center justify-center text-slate-300 text-[10px] font-black text-center">NENHUM PROCESSO ESPECIAL LANÇADO</div>
                  )}
                </ResponsiveContainer>
              </div>
            </div>

            <div className="lg:col-span-2 bg-white p-8 rounded-[32px] shadow-sm border border-slate-200 flex flex-col justify-center">
              <h3 className="text-lg font-black text-slate-800 mb-8 uppercase tracking-tight">Equilíbrio da Demanda Atual</h3>
              <div className="space-y-10">
                <div>
                  <div className="flex justify-between text-xs font-black text-slate-500 uppercase mb-3">
                    <span className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-slate-400"></div> Pagamentos Comuns</span>
                    <span className="text-slate-800">{strategicAnalysis.commonsCount} unidades</span>
                  </div>
                  <div className="w-full bg-slate-100 h-5 rounded-full overflow-hidden border border-slate-50">
                    <div className="bg-slate-500 h-full transition-all duration-1000 shadow-inner" style={{ width: `${(strategicAnalysis.commonsCount / (strategicAnalysis.commonsCount + strategicAnalysis.specialsCount || 1)) * 100}%` }}></div>
                  </div>
                </div>
                <div>
                  <div className="flex justify-between text-xs font-black text-amber-600 uppercase mb-3">
                    <span className="flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse"></div> Licitação / Diária</span>
                    <span className="text-amber-800">{strategicAnalysis.specialsCount} unidades</span>
                  </div>
                  <div className="w-full bg-amber-50 h-5 rounded-full overflow-hidden border border-amber-100">
                    <div className="bg-amber-500 h-full transition-all duration-1000 shadow-inner" style={{ width: `${(strategicAnalysis.specialsCount / (strategicAnalysis.commonsCount + strategicAnalysis.specialsCount || 1)) * 100}%` }}></div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Gráfico Ranking de Equipe */}
          <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
            <h3 className="text-xl font-extrabold text-slate-800 mb-8 flex items-center gap-3">
              <div className="w-2 h-8 bg-blue-600 rounded-full"></div>
              Ranking de Produção por Analista
            </h3>
            <div className="h-96 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={teamData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={12} fontWeight={700} stroke="#64748b" />
                  <YAxis axisLine={false} tickLine={false} fontSize={11} stroke="#94a3b8" />
                  <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                  <Legend verticalAlign="top" align="right" />
                  <Bar dataKey="processos" name="Processos" fill="#3b82f6" radius={[6, 6, 0, 0]} barSize={24} />
                  <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[6, 6, 0, 0]} barSize={24} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* Evolução e Categorias */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
              <h3 className="text-xl font-extrabold text-slate-800 mb-8">Evolução de Carga Diária</h3>
              <div className="h-80 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={evolutionData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="date" tickFormatter={(v) => v.split('-').reverse().slice(0,2).join('/')} fontSize={10} stroke="#94a3b8" />
                    <YAxis fontSize={10} stroke="#94a3b8" />
                    <Tooltip contentStyle={{ borderRadius: '12px' }} />
                    <Area type="monotone" dataKey="processos" name="Processos" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.05} strokeWidth={3} />
                    <Area type="monotone" dataKey="notas" name="Notas" stroke="#10b981" fill="#10b981" fillOpacity={0.05} strokeWidth={3} />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            </div>

            <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200">
              <h3 className="text-xl font-extrabold text-slate-800 mb-8">Volume por Categoria</h3>
              <div className="h-80 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={categoryData} cx="50%" cy="50%" innerRadius={60} outerRadius={90} paddingAngle={5} dataKey="value">
                      {categoryData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '12px' }} />
                    <Legend />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </div>
          </div>

          {/* IA Insights */}
          <div className="bg-slate-900 rounded-[40px] p-10 text-white shadow-2xl relative overflow-hidden group">
            <div className="flex flex-col md:flex-row items-center justify-between gap-12 relative z-10">
              <div className="flex-1">
                <div className="flex items-center gap-4 mb-6">
                  <div className="bg-blue-600 p-3 rounded-2xl animate-pulse">
                    <Icons.Sparkles />
                  </div>
                  <h2 className="text-3xl font-black tracking-tight">IA Diagnóstico</h2>
                </div>
                <p className="text-slate-400 text-lg mb-10 max-w-lg leading-relaxed font-medium">
                  Análise baseada nos filtros atuais de <strong>{processType === 'all' ? 'toda a carga' : processType === 'common' ? 'pagamentos comuns' : 'especiais'}</strong>.
                </p>
                {!aiInsight && !loadingAi && (
                  <button onClick={handleGetInsights} className="bg-white text-slate-900 px-10 py-5 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-blue-50 transition-all shadow-2xl">Gerar Análise IA</button>
                )}
              </div>
              {loadingAi && <div className="animate-spin h-12 w-12 border-4 border-white/20 border-t-white rounded-full"></div>}
              {aiInsight && !loadingAi && (
                <div className="flex-1 bg-white/5 backdrop-blur-3xl rounded-[32px] p-8 border border-white/10 max-h-[400px] overflow-y-auto custom-scrollbar text-slate-200 shadow-inner">
                  <div className="text-base leading-relaxed whitespace-pre-wrap font-medium">{aiInsight}</div>
