    <div className="space-y-8 pb-20">
      {/* Filtros Superiores */}
      <div className="bg-white p-8 rounded-[32px] shadow-sm border border-slate-200 space-y-8">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="font-black text-slate-800 text-lg uppercase tracking-tight">Tipo de Processo</h3>
            <p className="text-xs text-slate-400 font-bold">Selecione a aba para visualizar os gráficos específicos</p>
          </div>
          <div className="flex p-1.5 bg-slate-100 rounded-2xl border border-slate-200">
            <button 
              onClick={() => setProcessType('all')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all ${processType === 'all' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}
            >
              VISÃO GERAL
            </button>
            <button 
              onClick={() => setProcessType('common')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all ${processType === 'common' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400'}`}
            >
              PAGAMENTO COMUM
            </button>
            <button 
              onClick={() => setProcessType('special')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all ${processType === 'special' ? 'bg-amber-500 text-white shadow-lg' : 'text-slate-400'}`}
            >
              LICITAÇÃO / DIÁRIA
            </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pt-6 border-t border-slate-100">
          <div className="space-y-4">
             <div className="flex items-center gap-2 text-slate-400 text-[10px] font-black uppercase tracking-widest"><Icons.Calendar /> Período</div>
             <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-xl border border-slate-200 self-start">
               <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
               <span className="text-slate-300">|</span>
               <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
             </div>
          </div>
          <div className="space-y-4">
             <div className="flex items-center gap-2 text-slate-400 text-[10px] font-black uppercase tracking-widest"><Icons.People /> Equipe</div>
             <div className="flex flex-wrap gap-2">
               <button onClick={() => setSelectedPeopleIds([])} className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${selectedPeopleIds.length === 0 ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-400 border-slate-200'}`}>TODOS</button>
               {state.people.map(p => (
                 <button key={p.id} onClick={() => togglePerson(p.id)} className={`px-4 py-2 rounded-xl text-[10px] font-bold border transition-all ${selectedPeopleIds.includes(p.id) ? 'bg-blue-50 text-blue-700 border-blue-200' : 'bg-white text-slate-400 border-slate-200'}`}>{p.name}</button>
               ))}
             </div>
          </div>
        </div>
      </div>

      {/* MÉTRICAS RÁPIDAS */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm border-l-4 border-l-blue-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Processos Comuns</p>
          <p className="text-3xl font-black text-slate-800 mt-1">{commonTasks.reduce((acc, t) => acc + t.processQuantity, 0)}</p>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm border-l-4 border-l-amber-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Licitação / Diária</p>
          <p className="text-3xl font-black text-amber-600 mt-1">{specialTasks.reduce((acc, t) => acc + t.processQuantity, 0)}</p>
        </div>
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm border-l-4 border-l-emerald-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Total Notas Fiscais</p>
          <p className="text-3xl font-black text-emerald-600 mt-1">{filteredTasks.reduce((acc, t) => acc + (t.invoiceQuantity || 0), 0)}</p>
        </div>
      </div>

      {/* ABA: LICITAÇÃO / DIÁRIA (SOMENTE PIZZA) */}
      {(processType === 'special' || processType === 'all') && (
        <div className="animate-in slide-in-from-bottom-4 duration-500">
          <div className="bg-white p-10 rounded-[40px] shadow-sm border border-slate-200">
            <div className="flex items-center gap-4 mb-10">
              <div className="w-1.5 h-10 bg-amber-500 rounded-full"></div>
              <div>
                <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Setor de Licitação & Diárias</h3>
                <p className="text-slate-400 font-bold text-sm">Quantitativo detalhado por subcategoria</p>
              </div>
            </div>

            <div className="h-[400px] w-full">
              {hasSpecialData ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={specialPieData} 
                      cx="50%" cy="50%" 
                      innerRadius={80} outerRadius={120} 
                      paddingAngle={10} 
                      dataKey="value"
                      label={({ name, value }) => `${name}: ${value}`}
                    >
                      {specialPieData.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} strokeWidth={0} />
                      ))}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)', fontWeight: 'bold' }} />
                    <Legend verticalAlign="bottom" height={36}/>
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-300">
