      {/* ABA: PAGAMENTO COMUM (GRAFICOS ANTIGOS) */}
      {(processType === 'common' || processType === 'all') && (
        <div className="space-y-8 animate-in slide-in-from-bottom-4 duration-500">
          {/* Ranking Equipe */}
