              <div className="w-1.5 h-10 bg-blue-600 rounded-full"></div>
              <div>
                <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Desempenho: Pagamentos Comuns</h3>
                <p className="text-slate-400 font-bold text-sm">Ranking de analistas (Processos vs Notas)</p>
              </div>
            </div>
            <div className="h-96 w-full">
              {hasCommonData ? (
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={teamData}>
