                    <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '16px', border: 'none' }} />
                    <Legend verticalAlign="top" align="right" />
                    <Bar dataKey="processos" name="Processos" fill="#3b82f6" radius={[6, 6, 0, 0]} barSize={24} />
                    <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[6, 6, 0, 0]} barSize={24} />
                  </BarChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex items-center justify-center text-slate-300 font-black text-xs uppercase">Sem dados comuns</div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Evolução */}
            <div className="bg-white p-10 rounded-[40px] shadow-sm border border-slate-200">
              <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Evolução do Fluxo</h3>
              <div className="h-80 w-full">
                {hasCommonData ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <AreaChart data={evolutionData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="date" tickFormatter={(v) => v.split('-').reverse().slice(0,2).join('/')} fontSize={10} stroke="#94a3b8" />
                      <YAxis fontSize={10} stroke="#94a3b8" />
                      <Tooltip />
                      <Area type="monotone" dataKey="processos" name="Processos" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.05} strokeWidth={3} />
                      <Area type="monotone" dataKey="notas" name="Notas" stroke="#10b981" fill="#10b981" fillOpacity={0.05} strokeWidth={3} />
                    </AreaChart>
                  </ResponsiveContainer>
                ) : (
                  <div className="h-full flex items-center justify-center text-slate-300 text-xs font-black">Sem evolução no período</div>
                )}
              </div>
            </div>

            {/* Pizza de Categorias Comuns */}
            <div className="bg-white p-10 rounded-[40px] shadow-sm border border-slate-200">
              <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Mix de Serviços</h3>
              <div className="h-80 w-full">
                {hasCommonData ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                      <Pie data={categoryPieData} cx="50%" cy="50%" innerRadius={60} outerRadius={90} paddingAngle={5} dataKey="value">
                        {categoryPieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} strokeWidth={0}/>)}
                      </Pie>
                      <Tooltip contentStyle={{ borderRadius: '15px' }} />
                      <Legend />
                    </PieChart>
                  </ResponsiveContainer>
                ) : (
                  <div className="h-full flex items-center justify-center text-slate-300 text-xs font-black">Sem serviços registrados</div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* IA Diagnostics */}
      <div className="bg-slate-900 rounded-[40px] p-10 text-white shadow-2xl relative overflow-hidden">
        <div className="flex flex-col md:flex-row items-center justify-between gap-12 relative z-10">
          <div className="flex-1">
            <div className="flex items-center gap-4 mb-6">
              <div className="bg-blue-600 p-3 rounded-2xl animate-pulse"><Icons.Sparkles /></div>
              <h2 className="text-3xl font-black tracking-tight uppercase">Diagnóstico IA</h2>
            </div>
            <p className="text-slate-400 text-lg mb-10 max-w-lg leading-relaxed font-medium italic">
              "Clique para analisar a eficiência entre processos comuns e especiais no período selecionado."
            </p>
            {!aiInsight && !loadingAi && (
              <button onClick={handleGetInsights} className="bg-white text-slate-900 px-10 py-5 rounded-2xl font-black text-sm uppercase tracking-widest hover:bg-blue-50 transition-all shadow-2xl">Gerar Análise Geral</button>
            )}
          </div>
          {loadingAi && <div className="animate-spin h-12 w-12 border-4 border-white/20 border-t-white rounded-full"></div>}
          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/5 backdrop-blur-3xl rounded-[32px] p-8 border border-white/10 max-h-[400px] overflow-y-auto custom-scrollbar text-slate-200">
              <div className="text-base leading-relaxed whitespace-pre-wrap font-medium">{aiInsight}</div>
              <button onClick={() => setAiInsight(null)} className="mt-6 text-xs font-bold text-slate-500 hover:text-white uppercase tracking-widest">Fechar Diagnóstico</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

