              className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all ${activeTab === 'common' ? 'bg-white text-slate-800 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
            >
              PAGAMENTO COMUM
            </button>
            <button 
              onClick={() => setActiveTab('special')}
              className={`px-6 py-2.5 rounded-xl text-xs font-black transition-all ${activeTab === 'special' ? 'bg-amber-500 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'}`}
