        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[6px] border-l-blue-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Processos Comuns</p>
          <h4 className="text-4xl font-black text-slate-800 mt-2">{commonTasks.reduce((acc, t) => acc + t.processQuantity, 0)}</h4>
        </div>
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[6px] border-l-amber-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Especiais (Licitação/Diária)</p>
          <h4 className="text-4xl font-black text-amber-600 mt-2">{specialTasks.reduce((acc, t) => acc + t.processQuantity, 0)}</h4>
        </div>
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[6px] border-l-emerald-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Notas Fiscais Emitidas</p>
          <h4 className="text-4xl font-black text-emerald-600 mt-2">{filteredTasks.reduce((acc, t) => acc + (t.invoiceQuantity || 0), 0)}</h4>
        </div>
      </div>

      {/* CONTEÚDO DAS ABAS */}
      <div className="space-y-12">
        {/* ABA 1: LICITAÇÃO / DIÁRIA - APENAS PIZZA */}
        {(activeTab === 'special' || activeTab === 'all') && (
          <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
            <div className="flex flex-col md:flex-row md:items-center justify-between mb-10 gap-4">
              <div className="flex items-center gap-4">
                <div className="w-2 h-10 bg-amber-500 rounded-full"></div>
                <div>
                  <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Setor de Licitações & Diárias</h3>
                  <p className="text-slate-400 text-sm font-bold italic">Quantitativo por subcategoria especial</p>
                </div>
              </div>
            </div>

            <div className="h-[450px]">
              {specialTasks.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={specialPieData} 
                      cx="50%" cy="50%" 
                      innerRadius={80} outerRadius={140} 
                      paddingAngle={8} 
                      dataKey="value"
                      label={({ name, value }) => `${name}: ${value}`}
                    >
                      {specialPieData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} strokeWidth={0} />)}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '24px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)', fontWeight: 'bold' }} />
                    <Legend verticalAlign="bottom" height={40}/>
                  </PieChart>
                </ResponsiveContainer>
              ) : <EmptyState message="Sem processos de Licitação ou Diária neste período" />}
            </div>
          </div>
        )}

        {/* ABA 2: PAGAMENTO COMUM - GRÁFICOS ANTIGOS */}
        {(activeTab === 'common' || activeTab === 'all') && (
          <div className="space-y-12">
            {/* Gráfico de Barras - Ranking */}
            <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
              <div className="flex items-center gap-4 mb-10">
                <div className="w-2 h-10 bg-blue-600 rounded-full"></div>
                <div>
                  <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Ranking de Equipe (Comuns)</h3>
                  <p className="text-slate-400 text-sm font-bold italic">Volume de Processos vs Notas Fiscais</p>
                </div>
              </div>
              <div className="h-96">
                {commonTasks.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={teamDataCommon}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={12} fontWeight={800} stroke="#64748b" />
                      <YAxis axisLine={false} tickLine={false} fontSize={11} stroke="#94a3b8" />
                      <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '20px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                      <Legend verticalAlign="top" align="right" />
                      <Bar dataKey="processos" name="Processos" fill="#3b82f6" radius={[8, 8, 0, 0]} barSize={28} />
                      <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[8, 8, 0, 0]} barSize={28} />
                    </BarChart>
                  </ResponsiveContainer>
                ) : <EmptyState message="Sem registros de pagamentos comuns encontrados" />}
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              {/* Evolução Diária */}
              <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
                <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Evolução do Fluxo</h3>
                <div className="h-80">
                  {commonTasks.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={evolutionDataCommon}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis dataKey="date" tickFormatter={(v) => v.split('-').reverse().slice(0,2).join('/')} fontSize={10} fontWeight={700} stroke="#94a3b8" />
                        <YAxis fontSize={10} stroke="#94a3b8" />
                        <Tooltip contentStyle={{ borderRadius: '15px' }} />
                        <Area type="monotone" dataKey="processos" name="Processos" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.05} strokeWidth={4} />
                        <Area type="monotone" dataKey="notas" name="Notas" stroke="#10b981" fill="#10b981" fillOpacity={0.05} strokeWidth={4} />
                      </AreaChart>
                    </ResponsiveContainer>
                  ) : <EmptyState message="Sem dados de evolução temporal" />}
                </div>
              </div>

              {/* Pizza de Categorias Comuns */}
              <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
                <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Volume por Categoria</h3>
                <div className="h-80">
                  {commonTasks.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={categoryPieDataCommon} cx="50%" cy="50%" innerRadius={60} outerRadius={100} paddingAngle={6} dataKey="value">
                          {categoryPieDataCommon.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} strokeWidth={0}/>)}
                        </Pie>
                        <Tooltip contentStyle={{ borderRadius: '20px' }} />
                        <Legend />
                      </PieChart>
                    </ResponsiveContainer>
                  ) : <EmptyState message="Sem distribuição de categorias disponível" />}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* DIAGNÓSTICO IA (Footer) */}
      <div className="bg-slate-900 rounded-[56px] p-12 text-white shadow-2xl relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-96 h-96 bg-blue-600/10 rounded-full blur-3xl -mr-48 -mt-48 group-hover:bg-blue-600/20 transition-all duration-1000"></div>
        <div className="flex flex-col md:flex-row items-center justify-between gap-12 relative z-10">
          <div className="flex-1">
            <div className="flex items-center gap-4 mb-8">
              <div className="bg-blue-600 p-4 rounded-3xl animate-pulse shadow-xl shadow-blue-500/20"><Icons.Sparkles /></div>
              <h2 className="text-3xl font-black tracking-tight uppercase tracking-widest">IA Inteligência</h2>
            </div>
            <p className="text-slate-400 text-lg mb-12 max-w-xl leading-relaxed font-medium">
              Gere uma análise estratégica cruzando dados de <strong>Licitações</strong>, <strong>Diárias</strong> e <strong>Pagamentos Comuns</strong> para otimizar sua equipe.
            </p>
            {!aiInsight && !loadingAi && (
              <button 
                onClick={handleGetInsights} 
                disabled={filteredTasks.length === 0}
                className="bg-white text-slate-900 px-12 py-5 rounded-[24px] font-black text-sm uppercase tracking-widest hover:bg-blue-50 transition-all shadow-2xl disabled:opacity-50 disabled:cursor-not-allowed"
              >
                Gerar Diagnóstico Estratégico
              </button>
            )}
          </div>

          {loadingAi && (
            <div className="flex flex-col items-center gap-6">
              <div className="animate-spin h-14 w-14 border-[5px] border-white/20 border-t-white rounded-full"></div>
              <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Processando métricas...</p>
            </div>
          )}

          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/5 backdrop-blur-3xl rounded-[40px] p-10 border border-white/10 max-h-[500px] overflow-y-auto custom-scrollbar text-slate-200 shadow-inner">
              <div className="text-base leading-relaxed whitespace-pre-wrap font-medium">{aiInsight}</div>
              <button onClick={() => setAiInsight(null)} className="mt-8 text-[10px] font-black text-slate-500 hover:text-white uppercase tracking-widest border-t border-white/5 pt-6 w-full text-left">Limpar e fechar diagnóstico</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

type TabType = 'all' | 'common' | 'special';

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  // Ajuste inicial para pegar um período largo caso o usuário não tenha cadastros recentes
  const today = new Date().toISOString().split('T')[0];
  const defaultStart = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  const [startDate, setStartDate] = useState<string>(defaultStart);
  const [endDate, setEndDate] = useState<string>(today);
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState<TabType>('all');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Detecção inteligente de categorias (ignora acentos e maiúsculas)
  const isSpecialCategory = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return name.includes('licitacao') || name.includes('diaria') || name.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  // Filtro de Tarefas
  const filteredTasks = useMemo(() => {
    return state.tasks.filter(t => {
      const dateMatch = t.date >= startDate && t.date <= endDate;
      const personMatch = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
      return dateMatch && personMatch;
    });
  }, [state.tasks, startDate, endDate, selectedPeopleIds]);

  const commonTasks = useMemo(() => filteredTasks.filter(t => !isSpecialCategory(t.serviceCategoryId)), [filteredTasks, state.serviceCategories]);
  const specialTasks = useMemo(() => filteredTasks.filter(t => isSpecialCategory(t.serviceCategoryId)), [filteredTasks, state.serviceCategories]);

  // --- DADOS PARA PAGAMENTO COMUM (GRAFICOS ANTIGOS) ---
  const teamDataCommon = useMemo(() => {
    return state.people.map(person => {
      const pTasks = commonTasks.filter(t => t.personId === person.id);
      return {
        name: person.name,
        processos: pTasks.reduce((sum, t) => sum + t.processQuantity, 0),
        notas: pTasks.reduce((sum, t) => sum + (t.invoiceQuantity || 0), 0)
      };
    }).filter(d => d.processos > 0 || d.notas > 0).sort((a, b) => b.processos - a.processos);
  }, [commonTasks, state.people]);

  const evolutionDataCommon = useMemo(() => {
    const dates: Record<string, any> = {};
    commonTasks.forEach(t => {
      if (!dates[t.date]) dates[t.date] = { date: t.date, processos: 0, notas: 0 };
      dates[t.date].processos += t.processQuantity;
      dates[t.date].notas += (t.invoiceQuantity || 0);
    });
    return Object.values(dates).sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [commonTasks]);

  const categoryPieDataCommon = useMemo(() => {
    const counts: Record<string, number> = {};
    commonTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      if (cat) counts[cat.name] = (counts[cat.name] || 0) + t.processQuantity;
    });
    return Object.entries(counts).map(([name, value]) => ({
      name, value, color: state.serviceCategories.find(c => c.name === name)?.color || '#3b82f6'
    }));
  }, [commonTasks, state.serviceCategories]);

  // --- DADOS PARA LICITAÇÃO / DIÁRIA (APENAS PIZZA) ---
  const specialPieData = useMemo(() => {
    const counts: Record<string, number> = {};
    specialTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      if (cat) counts[cat.name] = (counts[cat.name] || 0) + t.processQuantity;
    });
    return Object.entries(counts).map(([name, value]) => ({
      name, value, color: state.serviceCategories.find(c => c.name === name)?.color || '#f59e0b'
    }));
  }, [specialTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (filteredTasks.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
      setAiInsight(insight || "IA sem análise para o período.");
    } catch (error) {
      setAiInsight("Erro ao gerar análise.");
    } finally {
      setLoadingAi(false);
    }
  };

  const EmptyNotice = ({ msg }: { msg: string }) => (
    <div className="flex flex-col items-center justify-center p-20 bg-slate-50 border-2 border-dashed border-slate-200 rounded-[32px] text-slate-400">
      <Icons.Calendar />
      <p className="mt-4 font-black text-xs uppercase tracking-widest">{msg}</p>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      {/* Filtros */}
      <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-200 space-y-8">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Produtividade 360</h3>
            <p className="text-xs text-slate-400 font-bold">Gerencie as abas para filtrar os gráficos</p>
          </div>
          <div className="flex p-1 bg-slate-100 rounded-2xl border border-slate-200">
            {[
              { id: 'all', label: 'VISÃO GERAL' },
              { id: 'common', label: 'PAGAMENTO COMUM' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all ${activeTab === tab.id ? 'bg-white text-blue-600 shadow-sm border border-slate-200' : 'text-slate-400'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pt-8 border-t border-slate-100">
          <div>
            <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 mb-3 tracking-widest">Periodo</label>
            <div className="flex items-center gap-3 bg-slate-50 p-2.5 rounded-2xl border border-slate-200 self-start">
              <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
              <div className="w-px h-6 bg-slate-200"></div>
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
            </div>
          </div>
          <div>
            <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 mb-3 tracking-widest">Colaboradores</label>
            <div className="flex flex-wrap gap-2">
              <button onClick={() => setSelectedPeopleIds([])} className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${selectedPeopleIds.length === 0 ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-400 border-slate-200'}`}>TODOS</button>
              {state.people.map(p => (
                <button key={p.id} onClick={() => togglePerson(p.id)} className={`px-4 py-2 rounded-xl text-[10px] font-bold border transition-all ${selectedPeopleIds.includes(p.id) ? 'bg-indigo-50 text-indigo-700 border-indigo-200 shadow-sm' : 'bg-white text-slate-400 border-slate-200'}`}>{p.name}</button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Cards de Resumo */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-8 border-l-blue-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Processos Comuns</p>
          <h4 className="text-4xl font-black text-slate-900 mt-2">{commonTasks.reduce((acc, t) => acc + t.processQuantity, 0)}</h4>
        </div>
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-8 border-l-amber-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Licitação / Diária</p>
          <h4 className="text-4xl font-black text-amber-600 mt-2">{specialTasks.reduce((acc, t) => acc + t.processQuantity, 0)}</h4>
        </div>
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-8 border-l-emerald-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Notas Fiscais</p>
          <h4 className="text-4xl font-black text-emerald-600 mt-2">{filteredTasks.reduce((acc, t) => acc + (t.invoiceQuantity || 0), 0)}</h4>
        </div>
      </div>

      {/* ÁREA DE GRÁFICOS */}
      <div className="space-y-12">
        {/* ABA: LICITAÇÃO / DIÁRIA (SÓ PIZZA) */}
        {(activeTab === 'special' || activeTab === 'all') && (
          <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
            <div className="flex items-center gap-4 mb-10">
              <div className="w-2 h-10 bg-amber-500 rounded-full"></div>
              <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Especial: Licitações & Diárias</h3>
            </div>
            {specialTasks.length > 0 ? (
              <div className="chart-wrapper">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={specialPieData} cx="50%" cy="50%" innerRadius={80} outerRadius={130} paddingAngle={8} dataKey="value" label={({name, value}) => `${name}: ${value}`}>
                      {specialPieData.map((e, i) => <Cell key={`c-${i}`} fill={e.color} />)}
                    </Pie>
                    <Tooltip contentStyle={{borderRadius: '20px', border: 'none', fontWeight: 'bold'}} />
                    <Legend verticalAlign="bottom" />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            ) : <EmptyNotice msg="Sem processos especiais no período" />}
          </div>
        )}

        {/* ABA: COMUM (GRÁFICOS ANTIGOS) */}
        {(activeTab === 'common' || activeTab === 'all') && (
          <div className="space-y-12">
            {/* Gráfico de Barras */}
            <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
              <div className="flex items-center gap-4 mb-10">
                <div className="w-2 h-10 bg-blue-600 rounded-full"></div>
                <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Ranking de Produção (Comum)</h3>
              </div>
              {commonTasks.length > 0 ? (
                <div className="chart-wrapper">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={teamDataCommon}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={12} fontWeight={800} stroke="#64748b" />
                      <YAxis axisLine={false} tickLine={false} fontSize={11} stroke="#94a3b8" />
                      <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{borderRadius: '20px', border: 'none'}} />
                      <Legend verticalAlign="top" align="right" />
                      <Bar dataKey="processos" name="Processos" fill="#3b82f6" radius={[8, 8, 0, 0]} barSize={25} />
                      <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[8, 8, 0, 0]} barSize={25} />
