import React, { useState, useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
}

type TabType = 'all' | 'common' | 'special';

const Dashboard: React.FC<DashboardProps> = ({ state }) => {
  // Ajuste para pegar um período longo inicial para garantir que dados apareçam
  const today = new Date().toISOString().split('T')[0];
  const defaultStart = new Date(Date.now() - 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  const [startDate, setStartDate] = useState<string>(defaultStart);
  const [endDate, setEndDate] = useState<string>(today);
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState<TabType>('all');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);

  // Detecção robusta de categorias especiais (Licitação / Diária)
  const isSpecialCategory = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return name.includes('licitacao') || name.includes('diaria') || name.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  // 1. Filtragem Central por Data e Pessoa
  const filteredTasks = useMemo(() => {
    return (state.tasks || []).filter(t => {
      const dateMatch = t.date >= startDate && t.date <= endDate;
      const personMatch = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
      return dateMatch && personMatch;
    });
  }, [state.tasks, startDate, endDate, selectedPeopleIds]);

  // 2. Divisão das tarefas por tipo de aba
  const commonTasks = useMemo(() => filteredTasks.filter(t => !isSpecialCategory(t.serviceCategoryId)), [filteredTasks, state.serviceCategories]);
  const specialTasks = useMemo(() => filteredTasks.filter(t => isSpecialCategory(t.serviceCategoryId)), [filteredTasks, state.serviceCategories]);

  // --- DADOS PARA PAGAMENTO COMUM (GRAFICOS ANTIGOS) ---
  const teamDataCommon = useMemo(() => {
    return (state.people || []).map(person => {
      const pTasks = commonTasks.filter(t => t.personId === person.id);
      return {
        name: person.name,
        processos: pTasks.reduce((sum, t) => sum + (Number(t.processQuantity) || 0), 0),
        notas: pTasks.reduce((sum, t) => sum + (Number(t.invoiceQuantity) || 0), 0)
      };
    }).filter(d => d.processos > 0 || d.notas > 0).sort((a, b) => b.processos - a.processos);
  }, [commonTasks, state.people]);

  const evolutionDataCommon = useMemo(() => {
    const dates: Record<string, any> = {};
    commonTasks.forEach(t => {
      if (!dates[t.date]) dates[t.date] = { date: t.date, processos: 0, notas: 0 };
      dates[t.date].processos += (Number(t.processQuantity) || 0);
      dates[t.date].notas += (Number(t.invoiceQuantity) || 0);
    });
    return Object.values(dates).sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [commonTasks]);

  const categoryPieDataCommon = useMemo(() => {
    const counts: Record<string, number> = {};
    commonTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      if (cat) counts[cat.name] = (counts[cat.name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(counts).map(([name, value]) => ({
      name, value, color: state.serviceCategories.find(c => c.name === name)?.color || '#3b82f6'
    }));
  }, [commonTasks, state.serviceCategories]);

  // --- DADOS PARA LICITAÇÃO / DIÁRIA (SÓ PIZZA) ---
  const specialPieData = useMemo(() => {
    const counts: Record<string, number> = {};
    specialTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      if (cat) counts[cat.name] = (counts[cat.name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(counts).map(([name, value]) => ({
      name, value, color: state.serviceCategories.find(c => c.name === name)?.color || '#f59e0b'
    }));
  }, [specialTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (filteredTasks.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
      setAiInsight(insight || "A IA não identificou tendências claras para este conjunto de dados.");
    } catch (error) {
      setAiInsight("Erro ao contactar a inteligência artificial.");
    } finally {
      setLoadingAi(false);
    }
  };

  const EmptyState = ({ message }: { message: string }) => (
    <div className="flex flex-col items-center justify-center p-20 bg-slate-50 border-2 border-dashed border-slate-200 rounded-[32px] text-slate-300">
      <Icons.Calendar />
      <p className="mt-4 font-black text-[10px] uppercase tracking-widest">{message}</p>
    </div>
  );

  return (
    <div className="space-y-8 pb-24">
      {/* FILTROS E ABAS */}
      <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-200 space-y-8">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Painel de Controle</h3>
            <p className="text-xs text-slate-400 font-bold">Gerenciamento de produtividade por categoria</p>
          </div>
          <div className="flex p-1 bg-slate-100 rounded-2xl border border-slate-200 overflow-x-auto">
            {[
              { id: 'all', label: 'VISÃO GERAL' },
              { id: 'common', label: 'PAGAMENTO COMUM' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-blue-600 shadow-sm border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pt-8 border-t border-slate-100">
          <div>
            <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 mb-3 tracking-widest">Periodo Analisado</label>
            <div className="flex items-center gap-3 bg-slate-50 p-2.5 rounded-2xl border border-slate-200 self-start">
              <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
              <div className="w-px h-6 bg-slate-200"></div>
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
            </div>
          </div>
          <div>
            <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 mb-3 tracking-widest">Colaboradores</label>
            <div className="flex flex-wrap gap-2">
              <button onClick={() => setSelectedPeopleIds([])} className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${selectedPeopleIds.length === 0 ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-white text-slate-400 border-slate-200 hover:bg-slate-50'}`}>TODOS</button>
              {state.people.map(p => (
                <button key={p.id} onClick={() => togglePerson(p.id)} className={`px-4 py-2 rounded-xl text-[10px] font-bold border transition-all ${selectedPeopleIds.includes(p.id) ? 'bg-indigo-50 text-indigo-700 border-indigo-200' : 'bg-white text-slate-400 border-slate-200 hover:bg-slate-50'}`}>{p.name}</button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* METRICAS DE RESUMO */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[8px] border-l-blue-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Processos Comuns</p>
          <h4 className="text-4xl font-black text-slate-900 mt-2">{commonTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[8px] border-l-amber-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Licitação / Diária</p>
          <h4 className="text-4xl font-black text-amber-600 mt-2">{specialTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[8px] border-l-emerald-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Notas Fiscais</p>
          <h4 className="text-4xl font-black text-emerald-600 mt-2">{filteredTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0)}</h4>
        </div>
      </div>

      {/* ÁREA DE GRÁFICOS */}
      <div className="space-y-12">
        {/* ABA: LICITAÇÃO / DIÁRIA (APENAS UM GRÁFICO DE PIZZA) */}
        {(activeTab === 'special' || activeTab === 'all') && (
          <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
            <div className="flex items-center gap-4 mb-10">
              <div className="w-2.5 h-10 bg-amber-500 rounded-full"></div>
              <div>
                <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Setor Licitações & Diárias</h3>
                <p className="text-slate-400 text-sm font-bold">Quantitativo por subcategoria de serviço especial</p>
              </div>
            </div>
            {specialTasks.length > 0 ? (
              <div className="chart-container-lg">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie 
                      data={specialPieData} 
                      cx="50%" cy="50%" 
                      innerRadius={80} outerRadius={140} 
                      paddingAngle={10} 
                      dataKey="value"
                      label={({ name, value }) => `${name}: ${value}`}
                    >
                      {specialPieData.map((e, i) => <Cell key={`sp-${i}`} fill={e.color} strokeWidth={0} />)}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '24px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                    <Legend verticalAlign="bottom" height={36}/>
                  </PieChart>
                </ResponsiveContainer>
              </div>
            ) : <EmptyState message="Sem lançamentos de Licitação ou Diária encontrados." />}
          </div>
        )}

        {/* ABA: PAGAMENTO COMUM (GRAFICOS ANTIGOS) */}
        {(activeTab === 'common' || activeTab === 'all') && (
          <div className="space-y-12">
            {/* Gráfico de Barras - Ranking */}
            <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
              <div className="flex items-center gap-4 mb-10">
                <div className="w-2.5 h-10 bg-blue-600 rounded-full"></div>
                <div>
                  <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Ranking de Analistas (Comum)</h3>
                  <p className="text-slate-400 text-sm font-bold">Comparativo: Processos vs Notas Fiscais</p>
                </div>
              </div>
              {commonTasks.length > 0 ? (
                <div className="chart-container-lg">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={teamDataCommon}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={12} fontWeight={800} stroke="#64748b" />
                      <YAxis axisLine={false} tickLine={false} fontSize={11} stroke="#94a3b8" />
                      <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '20px', border: 'none' }} />
                      <Legend verticalAlign="top" align="right" iconType="circle" />
                      <Bar dataKey="processos" name="Processos" fill="#3b82f6" radius={[8, 8, 0, 0]} barSize={26} />
                      <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[8, 8, 0, 0]} barSize={26} />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              ) : <EmptyState message="Sem registros de pagamentos comuns encontrados." />}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              {/* Gráfico de Área - Evolução */}
              <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
                <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Evolução do Fluxo</h3>
                {commonTasks.length > 0 ? (
                  <div className="chart-container-md">
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={evolutionDataCommon}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis dataKey="date" tickFormatter={(v) => v.split('-').reverse().slice(0,2).join('/')} fontSize={10} fontWeight={700} stroke="#94a3b8" />
                        <YAxis fontSize={10} stroke="#94a3b8" />
                        <Tooltip contentStyle={{ borderRadius: '16px' }} />
                        <Area type="monotone" dataKey="processos" name="Processos" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.08} strokeWidth={4} />
                        <Area type="monotone" dataKey="notas" name="Notas" stroke="#10b981" fill="#10b981" fillOpacity={0.08} strokeWidth={4} />
                      </AreaChart>
                    </ResponsiveContainer>
                  </div>
                ) : <EmptyState message="Sem evolução temporal." />}
              </div>

              {/* Gráfico de Pizza - Mix Categorias */}
              <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
                <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Volume por Serviço</h3>
                {commonTasks.length > 0 ? (
                  <div className="chart-container-md">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={categoryPieDataCommon} cx="50%" cy="50%" innerRadius={60} outerRadius={100} paddingAngle={6} dataKey="value">
                          {categoryPieDataCommon.map((e, i) => <Cell key={`pi-${i}`} fill={e.color} strokeWidth={0}/>)}
                        </Pie>
                        <Tooltip contentStyle={{ borderRadius: '20px' }} />
                        <Legend iconType="rect" />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
                ) : <EmptyState message="Sem mix de serviços cadastrados." />}
              </div>
            </div>
          </div>
        )}
      </div>

      {/* IA DIAGNOSTICS */}
      <div className="bg-slate-900 rounded-[64px] p-12 text-white shadow-2xl relative overflow-hidden group mt-12">
        <div className="flex flex-col md:flex-row items-center justify-between gap-12 relative z-10">
          <div className="flex-1">
            <div className="flex items-center gap-4 mb-6">
              <div className="bg-blue-600 p-4 rounded-3xl animate-pulse shadow-xl shadow-blue-500/20"><Icons.Sparkles /></div>
              <h2 className="text-3xl font-black tracking-tight uppercase tracking-widest">Análise de IA</h2>
            </div>
            <p className="text-slate-400 text-lg mb-10 max-w-xl leading-relaxed font-medium italic">
              "Clique para analisar como o volume de Licitações/Diárias está afetando o tempo médio de pagamentos comuns."
            </p>
            {!aiInsight && !loadingAi && (
              <button 
                onClick={handleGetInsights} 
                disabled={filteredTasks.length === 0}
                className="bg-white text-slate-900 px-12 py-5 rounded-[24px] font-black text-sm uppercase tracking-widest hover:bg-blue-50 transition-all shadow-2xl disabled:opacity-50"
              >
                Gerar Diagnóstico Estratégico
              </button>
            )}
          </div>
          {loadingAi && <div className="animate-spin h-14 w-14 border-[6px] border-white/20 border-t-white rounded-full"></div>}
          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/5 backdrop-blur-3xl rounded-[40px] p-10 border border-white/10 max-h-[500px] overflow-y-auto custom-scrollbar text-slate-200 shadow-inner">
              <div className="text-base leading-relaxed whitespace-pre-wrap font-medium">{aiInsight}</div>
              <button onClick={() => setAiInsight(null)} className="mt-8 text-[10px] font-black text-slate-500 hover:text-white uppercase tracking-widest border-t border-white/5 pt-6 w-full text-left">Fechar análise</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

