        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 pt-8 border-t border-slate-100">
          <div>
            <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 mb-3 tracking-widest">Periodo de Análise</label>
            <div className="flex items-center gap-3 bg-slate-50 p-2.5 rounded-2xl border border-slate-200 w-fit">
              <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
              <div className="w-px h-6 bg-slate-200"></div>
              <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="bg-transparent text-sm font-bold text-slate-700 outline-none px-2" />
            </div>
          </div>
          <div>
            <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 mb-3 tracking-widest">Filtrar por Equipe</label>
            <div className="flex flex-wrap gap-2">
              <button 
                onClick={() => setSelectedPeopleIds([])} 
                className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${selectedPeopleIds.length === 0 ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-100' : 'bg-white text-slate-400 border-slate-200 hover:bg-slate-50'}`}
              >
                TODOS OS MEMBROS
              </button>
              {state.people.map(p => (
                <button 
                  key={p.id} 
                  onClick={() => togglePerson(p.id)} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-bold border transition-all ${selectedPeopleIds.includes(p.id) ? 'bg-indigo-50 text-indigo-700 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}
