          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/5 backdrop-blur-3xl rounded-[40px] p-10 border border-white/10 max-h-[500px] overflow-y-auto custom-scrollbar text-slate-200">
              <div className="text-base leading-relaxed whitespace-pre-wrap font-medium">{aiInsight}</div>
              <button onClick={() => setAiInsight(null)} className="mt-8 text-[10px] font-black text-slate-500 hover:text-white uppercase tracking-widest border-t border-white/5 pt-6 w-full text-left">Fechar Análise</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

