              { id: 'all', label: 'VISÃO GERAL' },
              { id: 'common', label: 'PAGAMENTO COMUM' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-blue-600 shadow-sm border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}
