import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
  onRefresh?: () => Promise<void>;
}

type TabType = 'common' | 'special';
type PeriodPreset = 'hoje' | 'semanal' | 'quinzenal' | 'mensal' | 'trimestral' | 'anual' | 'custom';

const Dashboard: React.FC<DashboardProps> = ({ state, onRefresh }) => {
  const todayStr = new Date().toISOString().split('T')[0];

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>(todayStr);
  const [activePreset, setActivePreset] = useState<PeriodPreset>('mensal');
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState<TabType>('common');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Efeito para gerenciar os presets de data
  useEffect(() => {
    const now = new Date();
    let start = new Date();

    switch (activePreset) {
      case 'hoje':
        // Hoje
        break;
      case 'semanal':
        start.setDate(now.getDate() - 7);
        break;
      case 'quinzenal':
        start.setDate(now.getDate() - 15);
        break;
      case 'mensal':
        start.setDate(now.getDate() - 30);
        break;
      case 'trimestral':
        start.setDate(now.getDate() - 90);
        break;
      case 'anual':
        start.setDate(now.getDate() - 365);
        break;
      case 'custom':
        return; // Não altera se for custom
    }

    if (activePreset !== 'custom') {
      setStartDate(start.toISOString().split('T')[0]);
      setEndDate(now.toISOString().split('T')[0]);
    }
  }, [activePreset]);

  // Detecção de categorias especiais (Licitação / Diária)
  const isSpecialCategory = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return name.includes('licitacao') || name.includes('diaria') || name.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  const handleManualRefresh = async () => {
    if (onRefresh) {
      setIsRefreshing(true);
      await onRefresh();
      // Pequeno delay para a animação ser percebida
      setTimeout(() => setIsRefreshing(false), 600);
    }
  };

  // Filtragem centralizada
  const filteredTasks = useMemo(() => {
    const tasks = state.tasks || [];
    return tasks.filter(t => {
      const dateMatch = (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate);
      const personMatch = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
      return dateMatch && personMatch;
    });
  }, [state.tasks, startDate, endDate, selectedPeopleIds]);

  const commonTasks = filteredTasks.filter(t => !isSpecialCategory(t.serviceCategoryId));
  const specialTasks = filteredTasks.filter(t => isSpecialCategory(t.serviceCategoryId));

  // --- Processamento de Dados para Gráficos ---

  const barData = useMemo(() => {
    return state.people.map(person => {
      const pTasks = commonTasks.filter(t => t.personId === person.id);
      return {
        name: person.name,
        processos: pTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0),
        notas: pTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0)
      };
    }).filter(d => d.processos > 0 || d.notas > 0).sort((a, b) => b.processos - a.processos);
  }, [commonTasks, state.people]);

  const areaData = useMemo(() => {
    const map: Record<string, any> = {};
    commonTasks.forEach(t => {
      if (!map[t.date]) map[t.date] = { date: t.date, processos: 0, notas: 0 };
      map[t.date].processos += (Number(t.processQuantity) || 0);
      map[t.date].notas += (Number(t.invoiceQuantity) || 0);
    });
    return Object.values(map).sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [commonTasks]);

  const pieDataCommon = useMemo(() => {
    const counts: Record<string, number> = {};
    commonTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      if (cat) counts[cat.name] = (counts[cat.name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(counts).map(([name, value]) => ({
      name, value, color: state.serviceCategories.find(c => c.name === name)?.color || '#3b82f6'
    }));
  }, [commonTasks, state.serviceCategories]);

  const pieDataSpecial = useMemo(() => {
    const counts: Record<string, number> = {};
    specialTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      if (cat) counts[cat.name] = (counts[cat.name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(counts).map(([name, value]) => ({
      name, value, color: state.serviceCategories.find(c => c.name === name)?.color || '#f59e0b'
    }));
  }, [specialTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (filteredTasks.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
      setAiInsight(insight);
    } catch (e) {
      setAiInsight("Erro ao gerar análise inteligente.");
    } finally {
      setLoadingAi(false);
    }
  };

  const presets: { id: PeriodPreset, label: string }[] = [
    { id: 'hoje', label: 'Hoje' },
    { id: 'semanal', label: 'Semanal' },
    { id: 'quinzenal', label: 'Quinzenal' },
    { id: 'mensal', label: 'Mensal' },
    { id: 'trimestral', label: 'Trimestral' },
    { id: 'anual', label: 'Anual' },
    { id: 'custom', label: 'Personalizado' }
  ];

  const EmptyNotice = ({ msg }: { msg: string }) => (
    <div className="flex flex-col items-center justify-center h-full p-10 bg-slate-50 border-2 border-dashed border-slate-200 rounded-[32px] text-slate-300">
      <div className="opacity-20"><Icons.Calendar /></div>
      <p className="mt-4 font-black text-[10px] uppercase tracking-widest text-slate-400">{msg}</p>
    </div>
  );

  return (
    <div className="space-y-8 pb-20 fade-in">
      {/* SEÇÃO DE FILTROS APRIMORADA */}
      <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-200 space-y-8">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Painel Executivo</h3>
            <p className="text-xs text-slate-400 font-bold">Filtre por período e tipo de serviço</p>
          </div>
          <div className="flex p-1.5 bg-slate-100 rounded-2xl border border-slate-200 overflow-x-auto custom-scrollbar">
            {[
              { id: 'common', label: 'PROCESSOS DE PAGAMENTO' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-blue-600 shadow-sm border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="pt-8 border-t border-slate-100 space-y-8">
          {/* Presets de Período + Botão Refresh */}
          <div>
            <div className="flex items-center justify-between mb-4">
              <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 tracking-widest">Atalhos de Período</label>
              <button 
                onClick={handleManualRefresh}
                disabled={isRefreshing}
                className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-slate-50 border border-slate-200 text-slate-500 hover:text-blue-600 hover:bg-blue-50 hover:border-blue-100 transition-all active:scale-95 disabled:opacity-50"
                title="Atualizar dados manualmente"
              >
                <div className={isRefreshing ? 'animate-spin-slow' : ''}>
                  <Icons.Refresh />
                </div>
                <span className="text-[10px] font-black uppercase tracking-widest">Sincronizar</span>
              </button>
            </div>
            <div className="flex flex-wrap gap-2">
              {presets.map(p => (
                <button
                  key={p.id}
                  onClick={() => setActivePreset(p.id)}
                  className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${activePreset === p.id ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white text-slate-400 border-slate-200 hover:bg-slate-50'}`}
                >
                  {p.label.toUpperCase()}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Seleção de Datas Customizada */}
            <div className={`${activePreset !== 'custom' ? 'opacity-50 pointer-events-none' : ''}`}>
              <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 mb-3 tracking-widest">Período Customizado</label>
              <div className="flex items-center gap-3 bg-slate-50 p-2.5 rounded-2xl border border-slate-200 w-fit">
                <div className="flex flex-col px-2">
                  <span className="text-[8px] font-black text-slate-300 uppercase">Início</span>
                  <input type="date" value={startDate} onChange={(e) => { setStartDate(e.target.value); setActivePreset('custom'); }} className="bg-transparent text-sm font-bold text-slate-700 outline-none" />
                </div>
                <div className="w-px h-8 bg-slate-200"></div>
                <div className="flex flex-col px-2">
                  <span className="text-[8px] font-black text-slate-300 uppercase">Fim</span>
                  <input type="date" value={endDate} onChange={(e) => { setEndDate(e.target.value); setActivePreset('custom'); }} className="bg-transparent text-sm font-bold text-slate-700 outline-none" />
                </div>
              </div>
            </div>

            {/* Filtrar por Equipe */}
            <div>
              <label className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 mb-3 tracking-widest">Filtrar Equipe</label>
              <div className="flex flex-wrap gap-2 max-h-[120px] overflow-y-auto custom-scrollbar pr-2">
                <button 
                  onClick={() => setSelectedPeopleIds([])} 
                  className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${selectedPeopleIds.length === 0 ? 'bg-indigo-600 text-white border-indigo-600 shadow-lg shadow-indigo-100' : 'bg-white text-slate-400 border-slate-200 hover:bg-slate-50'}`}
                >
                  TODOS
                </button>
                {state.people.map(p => (
                  <button 
                    key={p.id} 
                    onClick={() => togglePerson(p.id)} 
                    className={`px-4 py-2 rounded-xl text-[10px] font-bold border transition-all ${selectedPeopleIds.includes(p.id) ? 'bg-indigo-50 text-indigo-700 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}
                  >
                    {p.name}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* CARDS DE RESUMO */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[8px] border-l-blue-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Processos de Pagamento</p>
          <h4 className="text-4xl font-black text-slate-900 mt-2">{commonTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[8px] border-l-amber-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Licitações / Diárias</p>
          <h4 className="text-4xl font-black text-amber-600 mt-2">{specialTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[8px] border-l-emerald-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Notas Fiscais</p>
          <h4 className="text-4xl font-black text-emerald-600 mt-2">{filteredTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0)}</h4>
        </div>
      </div>

      {/* ÁREA DOS GRÁFICOS */}
      <div className="space-y-12">
        {/* ABA: LICITAÇÃO / DIÁRIA */}
        {activeTab === 'special' && (
          <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
            <div className="flex items-center gap-4 mb-10">
              <div className="w-2.5 h-10 bg-amber-500 rounded-full"></div>
              <div>
                <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Setor Licitações & Diárias</h3>
                <p className="text-slate-400 text-sm font-bold">Distribuição por subcategoria de serviço especial</p>
              </div>
            </div>
            <div className="chart-container-lg">
              {pieDataSpecial.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={pieDataSpecial} cx="50%" cy="50%" innerRadius={80} outerRadius={140} paddingAngle={8} dataKey="value" label={({name, value}) => `${name}: ${value}`}>
                      {pieDataSpecial.map((e, i) => <Cell key={`sp-${i}`} fill={e.color} strokeWidth={0} />)}
                    </Pie>
                    <Tooltip contentStyle={{ borderRadius: '24px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
                    <Legend verticalAlign="bottom" height={36}/>
                  </PieChart>
                </ResponsiveContainer>
              ) : <EmptyNotice msg="Sem dados especiais no período selecionado." />}
            </div>
          </div>
        )}

        {/* ABA: PROCESSOS DE PAGAMENTO */}
        {activeTab === 'common' && (
          <div className="space-y-12">
            <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
              <div className="flex items-center gap-4 mb-10">
                <div className="w-2.5 h-10 bg-blue-600 rounded-full"></div>
                <div>
                  <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Ranking de Analistas (Pagamento)</h3>
                  <p className="text-slate-400 text-sm font-bold">Volumes de Processos e Notas por colaborador</p>
                </div>
              </div>
              <div className="chart-container-lg">
                {barData.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={barData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={12} fontWeight={800} stroke="#64748b" />
                      <YAxis axisLine={false} tickLine={false} fontSize={11} stroke="#94a3b8" />
                      <Tooltip cursor={{fill: '#f8fafc'}} contentStyle={{ borderRadius: '20px', border: 'none' }} />
                      <Legend verticalAlign="top" align="right" />
                      <Bar dataKey="processos" name="Processos" fill="#3b82f6" radius={[8, 8, 0, 0]} barSize={26} />
                      <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[8, 8, 0, 0]} barSize={26} />
                    </BarChart>
                  </ResponsiveContainer>
                ) : <EmptyNotice msg="Sem registros de pagamento encontrados no filtro atual." />}
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
                <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Evolução do Fluxo de Pagamento</h3>
                <div className="chart-container-md">
                  {areaData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={areaData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis dataKey="date" tickFormatter={(v) => v.split('-').reverse().slice(0,2).join('/')} fontSize={10} fontWeight={700} stroke="#94a3b8" />
                        <YAxis fontSize={10} stroke="#94a3b8" />
                        <Tooltip contentStyle={{ borderRadius: '16px' }} />
                        <Area type="monotone" dataKey="processos" name="Processos" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.08} strokeWidth={4} />
                        <Area type="monotone" dataKey="notas" name="Notas" stroke="#10b981" fill="#10b981" fillOpacity={0.08} strokeWidth={4} />
                      </AreaChart>
                    </ResponsiveContainer>
                  ) : <EmptyNotice msg="Sem histórico temporal." />}
                </div>
              </div>

              <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
                <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Mix de Serviços (Pagamento)</h3>
                <div className="chart-container-md">
                  {pieDataCommon.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={pieDataCommon} cx="50%" cy="50%" innerRadius={60} outerRadius={100} paddingAngle={6} dataKey="value">
                          {pieDataCommon.map((e, i) => <Cell key={`pi-${i}`} fill={e.color} strokeWidth={0}/>)}
                        </Pie>
                        <Tooltip contentStyle={{ borderRadius: '20px' }} />
                        <Legend iconType="rect" />
                      </PieChart>
                    </ResponsiveContainer>
                  ) : <EmptyNotice msg="Sem dados de categorias." />}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* IA ANALYTICS */}
      <div className="bg-slate-900 rounded-[64px] p-12 text-white shadow-2xl relative overflow-hidden group mt-12">
        <div className="flex flex-col md:flex-row items-center justify-between gap-12 relative z-10">
          <div className="flex-1">
            <div className="flex items-center gap-4 mb-6">
              <div className="bg-blue-600 p-4 rounded-3xl animate-pulse shadow-xl shadow-blue-500/20"><Icons.Sparkles /></div>
              <h2 className="text-3xl font-black uppercase tracking-widest">Diagnóstico IA</h2>
            </div>
            <p className="text-slate-400 text-lg mb-10 max-w-xl leading-relaxed font-medium">
              A inteligência artificial analisa os dados filtrados para identificar padrões de gargalo e eficiência nos fluxos de pagamento e licitações.
            </p>
            {!aiInsight && !loadingAi && (
              <button 
                onClick={handleGetInsights} 
                disabled={filteredTasks.length === 0}
                className="bg-white text-slate-900 px-12 py-5 rounded-[24px] font-black text-sm uppercase tracking-widest hover:bg-blue-50 transition-all shadow-2xl disabled:opacity-50"
              >
                Gerar Análise Estratégica
              </button>
            )}
          </div>
          {loadingAi && <div className="animate-spin h-14 w-14 border-[6px] border-white/20 border-t-white rounded-full"></div>}
          {aiInsight && !loadingAi && (
            <div className="flex-1 bg-white/5 backdrop-blur-3xl rounded-[40px] p-10 border border-white/10 max-h-[500px] overflow-y-auto custom-scrollbar text-slate-200">
              <div className="text-base leading-relaxed whitespace-pre-wrap font-medium">{aiInsight}</div>
              <button onClick={() => setAiInsight(null)} className="mt-8 text-[10px] font-black text-slate-500 hover:text-white uppercase tracking-widest border-t border-white/5 pt-6 w-full text-left">Fechar Análise</button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
  PieChart, Pie, Cell, AreaChart, Area
} from 'recharts';
import { AppState, Task, ServiceCategory } from '../types';
import { Icons } from '../constants';
import { getProductivityInsights } from '../services/geminiService';

interface DashboardProps {
  state: AppState;
  onRefresh?: () => Promise<void>;
}

type TabType = 'common' | 'special';
type PeriodPreset = 'hoje' | 'semanal' | 'quinzenal' | 'mensal' | 'trimestral' | 'anual' | 'custom';

const Dashboard: React.FC<DashboardProps> = ({ state, onRefresh }) => {
  // Função para pegar data local no formato YYYY-MM-DD
  const getLocalDateStr = (d: Date = new Date()) => {
    const offset = d.getTimezoneOffset();
    const localDate = new Date(d.getTime() - (offset * 60 * 1000));
    return localDate.toISOString().split('T')[0];
  };

  const [startDate, setStartDate] = useState<string>('');
  const [endDate, setEndDate] = useState<string>(getLocalDateStr());
  const [activePreset, setActivePreset] = useState<PeriodPreset>('mensal');
  const [selectedPeopleIds, setSelectedPeopleIds] = useState<string[]>([]);
  const [activeTab, setActiveTab] = useState<TabType>('common');
  const [aiInsight, setAiInsight] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  // Efeito para gerenciar os presets de data garantindo que cubram o dia de hoje
  useEffect(() => {
    const now = new Date();
    let start = new Date();

    switch (activePreset) {
      case 'hoje':
        break;
      case 'semanal':
        start.setDate(now.getDate() - 7);
        break;
      case 'quinzenal':
        start.setDate(now.getDate() - 15);
        break;
      case 'mensal':
        start.setDate(now.getDate() - 30);
        break;
      case 'trimestral':
        start.setDate(now.getDate() - 90);
        break;
      case 'anual':
        start.setDate(now.getDate() - 365);
        break;
      case 'custom':
        return;
    }

    if (activePreset !== 'custom') {
      setStartDate(getLocalDateStr(start));
      setEndDate(getLocalDateStr(now));
    }
  }, [activePreset]);

  // Detecção de categorias especiais mais resiliente
  const isSpecialCategory = (categoryId: string) => {
    const cat = state.serviceCategories.find(c => c.id === categoryId);
    if (!cat) return false;
    const name = cat.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return name.includes('licitacao') || name.includes('diaria') || name.includes('contrato');
  };

  const togglePerson = (id: string) => {
    setSelectedPeopleIds(prev => 
      prev.includes(id) ? prev.filter(pId => pId !== id) : [...prev, id]
    );
  };

  const handleManualRefresh = async () => {
    if (onRefresh) {
      setIsRefreshing(true);
      await onRefresh();
      setTimeout(() => setIsRefreshing(false), 600);
    }
  };

  // Filtragem centralizada - Garante que se startDate estiver vazio, mostre tudo até endDate
  const filteredTasks = useMemo(() => {
    const tasks = state.tasks || [];
    return tasks.filter(t => {
      const dateMatch = (!startDate || t.date >= startDate) && (!endDate || t.date <= endDate);
      const personMatch = selectedPeopleIds.length === 0 || selectedPeopleIds.includes(t.personId);
      return dateMatch && personMatch;
    });
  }, [state.tasks, startDate, endDate, selectedPeopleIds]);

  const commonTasks = filteredTasks.filter(t => !isSpecialCategory(t.serviceCategoryId));
  const specialTasks = filteredTasks.filter(t => isSpecialCategory(t.serviceCategoryId));

  // --- Processamento para Gráficos ---
  const barData = useMemo(() => {
    return state.people.map(person => {
      const pTasks = commonTasks.filter(t => t.personId === person.id);
      return {
        name: person.name,
        processos: pTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0),
        notas: pTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0)
      };
    }).filter(d => d.processos > 0 || d.notas > 0).sort((a, b) => b.processos - a.processos);
  }, [commonTasks, state.people]);

  const areaData = useMemo(() => {
    const map: Record<string, any> = {};
    commonTasks.forEach(t => {
      if (!map[t.date]) map[t.date] = { date: t.date, processos: 0, notas: 0 };
      map[t.date].processos += (Number(t.processQuantity) || 0);
      map[t.date].notas += (Number(t.invoiceQuantity) || 0);
    });
    return Object.values(map).sort((a: any, b: any) => a.date.localeCompare(b.date));
  }, [commonTasks]);

  const pieDataCommon = useMemo(() => {
    const counts: Record<string, number> = {};
    commonTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      if (cat) counts[cat.name] = (counts[cat.name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(counts).map(([name, value]) => ({
      name, value, color: state.serviceCategories.find(c => c.name === name)?.color || '#3b82f6'
    }));
  }, [commonTasks, state.serviceCategories]);

  const pieDataSpecial = useMemo(() => {
    const counts: Record<string, number> = {};
    specialTasks.forEach(t => {
      const cat = state.serviceCategories.find(c => c.id === t.serviceCategoryId);
      if (cat) counts[cat.name] = (counts[cat.name] || 0) + (Number(t.processQuantity) || 0);
    });
    return Object.entries(counts).map(([name, value]) => ({
      name, value, color: state.serviceCategories.find(c => c.name === name)?.color || '#f59e0b'
    }));
  }, [specialTasks, state.serviceCategories]);

  const handleGetInsights = async () => {
    if (filteredTasks.length === 0) return;
    setLoadingAi(true);
    try {
      const insight = await getProductivityInsights(filteredTasks, state.people, state.serviceCategories);
      setAiInsight(insight);
    } catch (e) {
      setAiInsight("Erro ao gerar análise inteligente.");
    } finally {
      setLoadingAi(false);
    }
  };

  const presets: { id: PeriodPreset, label: string }[] = [
    { id: 'hoje', label: 'Hoje' },
    { id: 'semanal', label: 'Semanal' },
    { id: 'quinzenal', label: 'Quinzenal' },
    { id: 'mensal', label: 'Mensal' },
    { id: 'trimestral', label: 'Trimestral' },
    { id: 'anual', label: 'Anual' },
    { id: 'custom', label: 'Personalizado' }
  ];

  const EmptyNotice = ({ msg }: { msg: string }) => (
    <div className="flex flex-col items-center justify-center h-full p-10 bg-slate-50 border-2 border-dashed border-slate-200 rounded-[32px] text-slate-300">
      <div className="opacity-20"><Icons.Calendar /></div>
      <p className="mt-4 font-black text-[10px] uppercase tracking-widest text-slate-400 text-center">{msg}</p>
    </div>
  );

  return (
    <div className="space-y-8 pb-20 fade-in">
      <div className="bg-white p-8 rounded-[40px] shadow-sm border border-slate-200 space-y-8">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Painel Executivo</h3>
            <p className="text-xs text-slate-400 font-bold">Filtre por período e tipo de serviço</p>
          </div>
          <div className="flex p-1.5 bg-slate-100 rounded-2xl border border-slate-200 overflow-x-auto custom-scrollbar">
            {[
              { id: 'common', label: 'PROCESSOS DE PAGAMENTO' },
              { id: 'special', label: 'LICITAÇÃO / DIÁRIA' }
            ].map(tab => (
              <button 
                key={tab.id}
                onClick={() => setActiveTab(tab.id as TabType)}
                className={`px-6 py-2.5 rounded-xl text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-blue-600 shadow-sm border border-slate-200' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </div>

        <div className="pt-8 border-t border-slate-100 space-y-8">
          <div>
            <div className="flex items-center justify-between mb-4">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Atalhos de Período</label>
              <button onClick={handleManualRefresh} disabled={isRefreshing} className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-slate-50 border border-slate-200 text-slate-500 hover:text-blue-600 hover:bg-blue-50 transition-all active:scale-95 disabled:opacity-50">
                <div className={isRefreshing ? 'animate-spin-slow' : ''}><Icons.Refresh /></div>
                <span className="text-[10px] font-black uppercase tracking-widest">Sincronizar</span>
              </button>
            </div>
            <div className="flex flex-wrap gap-2">
              {presets.map(p => (
                <button key={p.id} onClick={() => setActivePreset(p.id)} className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${activePreset === p.id ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-white text-slate-400 border-slate-200 hover:bg-slate-50'}`}>
                  {p.label.toUpperCase()}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className={`${activePreset !== 'custom' ? 'opacity-50 pointer-events-none' : ''}`}>
              <label className="text-[10px] font-black uppercase text-slate-400 mb-3 tracking-widest">Período Customizado</label>
              <div className="flex items-center gap-3 bg-slate-50 p-2.5 rounded-2xl border border-slate-200 w-fit">
                <input type="date" value={startDate} onChange={(e) => { setStartDate(e.target.value); setActivePreset('custom'); }} className="bg-transparent text-sm font-bold text-slate-700 outline-none" />
                <div className="w-px h-8 bg-slate-200"></div>
                <input type="date" value={endDate} onChange={(e) => { setEndDate(e.target.value); setActivePreset('custom'); }} className="bg-transparent text-sm font-bold text-slate-700 outline-none" />
              </div>
            </div>

            <div>
              <label className="text-[10px] font-black uppercase text-slate-400 mb-3 tracking-widest">Filtrar Equipe</label>
              <div className="flex flex-wrap gap-2">
                <button onClick={() => setSelectedPeopleIds([])} className={`px-4 py-2 rounded-xl text-[10px] font-black border transition-all ${selectedPeopleIds.length === 0 ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-slate-400 border-slate-200'}`}>TODOS</button>
                {state.people.map(p => (
                  <button key={p.id} onClick={() => togglePerson(p.id)} className={`px-4 py-2 rounded-xl text-[10px] font-bold border transition-all ${selectedPeopleIds.includes(p.id) ? 'bg-indigo-50 text-indigo-700 border-indigo-200' : 'bg-white text-slate-400 border-slate-200'}`}>{p.name}</button>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[8px] border-l-blue-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Processos de Pagamento</p>
          <h4 className="text-4xl font-black text-slate-900 mt-2">{commonTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[8px] border-l-amber-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Licitações / Diárias</p>
          <h4 className="text-4xl font-black text-amber-600 mt-2">{specialTasks.reduce((acc, t) => acc + (Number(t.processQuantity) || 0), 0)}</h4>
        </div>
        <div className="bg-white p-7 rounded-[32px] shadow-sm border border-slate-200 border-l-[8px] border-l-emerald-500">
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Notas Fiscais</p>
          <h4 className="text-4xl font-black text-emerald-600 mt-2">{filteredTasks.reduce((acc, t) => acc + (Number(t.invoiceQuantity) || 0), 0)}</h4>
        </div>
      </div>

      <div className="space-y-12">
        {activeTab === 'special' && (
          <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
            <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight mb-10">Setor Licitações & Diárias</h3>
            <div className="chart-container-lg">
              {pieDataSpecial.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={pieDataSpecial} cx="50%" cy="50%" innerRadius={80} outerRadius={140} paddingAngle={8} dataKey="value" label={({name, value}) => `${name}: ${value}`}>
                      {pieDataSpecial.map((e, i) => <Cell key={`sp-${i}`} fill={e.color} />)}
                    </Pie>
                    <Tooltip />
                    <Legend verticalAlign="bottom" height={36}/>
                  </PieChart>
                </ResponsiveContainer>
              ) : <EmptyNotice msg="Sem dados especiais no período selecionado. Verifique se os lançamentos foram feitos em categorias como 'Diária' ou 'Licitação'." />}
            </div>
          </div>
        )}

        {activeTab === 'common' && (
          <div className="space-y-12">
            <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
              <h3 className="text-2xl font-black text-slate-800 uppercase tracking-tight mb-10">Ranking de Analistas (Pagamento)</h3>
              <div className="chart-container-lg">
                {barData.length > 0 ? (
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={barData}>
                      <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                      <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={12} fontWeight={800} />
                      <YAxis axisLine={false} tickLine={false} fontSize={11} />
                      <Tooltip cursor={{fill: '#f8fafc'}} />
                      <Legend verticalAlign="top" align="right" />
                      <Bar dataKey="processos" name="Processos" fill="#3b82f6" radius={[8, 8, 0, 0]} barSize={26} />
                      <Bar dataKey="notas" name="Notas Fiscais" fill="#10b981" radius={[8, 8, 0, 0]} barSize={26} />
                    </BarChart>
                  </ResponsiveContainer>
                ) : <EmptyNotice msg="Nenhum registro de pagamento encontrado. Verifique os filtros de data e equipe." />}
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
              <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
                <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Evolução do Fluxo</h3>
                <div className="chart-container-md">
                  {areaData.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <AreaChart data={areaData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                        <XAxis dataKey="date" fontSize={10} stroke="#94a3b8" />
                        <YAxis fontSize={10} stroke="#94a3b8" />
                        <Tooltip />
                        <Area type="monotone" dataKey="processos" name="Processos" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.08} strokeWidth={4} />
                      </AreaChart>
                    </ResponsiveContainer>
                  ) : <EmptyNotice msg="Sem histórico temporal para exibir." />}
