              </div>
              <div className="bg-white p-10 rounded-[48px] shadow-sm border border-slate-200">
                <h3 className="text-xl font-black text-slate-800 mb-8 uppercase tracking-tight">Mix de Serviços</h3>
                <div className="chart-container-md">
                  {pieDataCommon.length > 0 ? (
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={pieDataCommon} cx="50%" cy="50%" innerRadius={60} outerRadius={100} paddingAngle={6} dataKey="value">
                          {pieDataCommon.map((e, i) => <Cell key={`pi-${i}`} fill={e.color}/>)}
