            </div>
          </div>
        )}
      </div>

      <div className="bg-slate-900 rounded-[64px] p-12 text-white shadow-2xl relative overflow-hidden group mt-12">
        <div className="flex flex-col md:flex-row items-center justify-between gap-12 relative z-10">
          <div className="flex-1">
            <h2 className="text-3xl font-black uppercase tracking-widest mb-6">Diagnóstico IA</h2>
            <p className="text-slate-400 text-lg mb-10 leading-relaxed">Clique para analisar os dados filtrados.</p>
            {!aiInsight && !loadingAi && (
              <button onClick={handleGetInsights} disabled={filteredTasks.length === 0} className="bg-white text-slate-900 px-12 py-5 rounded-[24px] font-black text-sm uppercase hover:bg-blue-50 transition-all disabled:opacity-50">Gerar Análise</button>
            )}
