                        <Area type="monotone" dataKey="processos" name="Processos" stroke="#3b82f6" fill="#3b82f6" fillOpacity={0.08} strokeWidth={3} />
                      </AreaChart>
                    </ResponsiveContainer>
                  ) : <EmptyNotice msg="Sem histórico temporal." />}
