import { AppState } from "../types";
import { dbService } from "./db";
import { cloudDb } from "./cloudDb";

// Chave única para este usuário/projeto no Firestore
const GROUP_ID = "main_productivity_v1";

export const apiService = {
  async loadState(): Promise<AppState | null> {
    try {
      // 1. Tenta carregar da nuvem (Firebase)
      const cloudState = await cloudDb.fetchState(GROUP_ID);
      if (cloudState) {
        // Sincroniza o banco local com o que veio da nuvem
        await dbService.save(cloudState);
        return cloudState;
      }

      // 2. Se falhar ou estiver vazio, tenta carregar do banco local (IndexedDB)
      const localState = await dbService.load();
      return localState;
    } catch (error) {
      console.error("Erro ao carregar dados:", error);
      return await dbService.load();
    }
  },

  async saveState(state: AppState): Promise<boolean> {
    try {
      // 1. Salva no banco local imediatamente (garante que não perca se a net cair)
      await dbService.save(state);

      // 2. Tenta sincronizar com o Firebase
      await cloudDb.syncState(GROUP_ID, state);

      return true;
    } catch (error) {
      console.error("Erro ao salvar dados (salvo apenas localmente):", error);
      return false;
    }
  }
};

